// Üretilen dosya: tool/ozgun/uret.py. Tarih · Millî Mücadele, Atatürk dönemi ve Cumhuriyet tarihi; 20. yüzyıl dünya tarihi (orta).
const ozHistory4Orta = <(String, String, List<String>, String)>[
  ('Mondros Ateşkes Antlaşması\'nın 7. maddesi, İtilaf Devletleri\'ne "güvenliklerini tehdit eden bir durum ortaya çıkarsa" stratejik bir noktayı işgal etme hakkı tanıyordu. Bu maddenin en önemli sonucu aşağıdakilerden hangisidir?', 'Anadolu\'nun herhangi bir yerinin işgaline hukuki kılıf hazırlaması', ['Osmanlı ordusunun tümüyle ve derhâl dağıtılmasını zorunlu kılması', 'Boğazların yönetimini Milletler Cemiyeti\'ne bırakması', 'Ermenilere Doğu Anadolu\'da bağımsız devlet vermesi'], '7. madde belirsiz ifadesi nedeniyle İtilaf Devletleri\'nin istedikleri her yeri işgal edebilmesinin yolunu açmıştır; bu yüzden antlaşmanın en tehlikeli maddesi sayılır.'),
  ('Mondros Ateşkesi\'nin ardından Musul\'u ateşkes imzalandıktan sonra işgal ederek antlaşmayı ilk ihlal eden devlet hangisidir?', 'İngiltere', ['Fransa', 'İtalya', 'Rusya'], 'İngilizler Musul\'u ateşkesten birkaç gün sonra, 3 Kasım 1918\'de işgal etmiş; bu, Mondros\'un ilk açık ihlali kabul edilir.'),
  ('Mondros sonrasında Antalya, Konya ve çevresini işgal eden devlet, St. Jean de Maurienne görüşmelerinde kendisine vaat edilen İzmir\'in Yunanistan\'a bırakılmasına tepki göstermiştir. Bu devlet hangisidir?', 'İtalya', ['Fransa', 'İngiltere', 'Amerika Birleşik Devletleri'], 'İtalya, 1917 St. Jean de Maurienne Antlaşması\'yla kendisine vaat edilen İzmir\'in Yunanistan\'a verilmesinden rahatsız olmuş, bu durum İtilaf içinde ayrılığa yol açmıştır.'),
  ('Wilson İlkeleri\'nin 12. maddesinin Türk milleti açısından önemi aşağıdakilerden hangisidir?', 'Türklerin çoğunlukta olduğu yerlerde egemenlik hakkı tanıması', ['Boğazların doğrudan Türk egemenliğine bırakılmasını öngörmesi', 'Kapitülasyonların kaldırılmasını şart koşması', 'Osmanlı borçlarının silinmesini önermesi'], 'Wilson\'un 14 ilkesinin 12. maddesi, Türk çoğunluklu bölgelerde Türklere egemenlik verilmesini öngörüyordu; Wilsonculuk Cemiyeti de bu maddeye dayanarak Amerikan mandasını savunmuştur.'),
  ('Kilikya Cemiyeti, Trakya-Paşaeli Cemiyeti ve Milli Kongre Cemiyeti ortak bir özelliğe sahiptir. Bu ortak özellik aşağıdakilerden hangisidir?', 'Millî varlığa yararlı cemiyetler arasında yer almaları', ['İngiliz himayesini açıkça savunmuş olmaları', 'Ermeni ve Rum azınlıklarca kurulmaları', 'Saltanatın kaldırılmasını amaçlamaları'], 'Bu üç cemiyet işgallere karşı Türk halkının haklarını savunmak için kurulmuş, Millî Mücadele\'ye destek veren yararlı cemiyetlerdendir.'),
  ('Rumların Karadeniz kıyısında bağımsız bir devlet kurma amacını taşıyan cemiyet hangisidir?', 'Pontus Rum Cemiyeti', ['Etnik-i Eterya', 'Taşnak Cemiyeti', 'Alyans İsrailit Cemiyeti'], 'Pontus Rum Cemiyeti, Samsun ve çevresini merkez alan bir Rum devleti kurmayı amaçlamıştır; Mustafa Kemal\'in Samsun\'a gönderilme gerekçelerinden biri de bölgedeki karışıklıklardır.'),
  ('Yararlı cemiyetlerin genel olarak bölgesel nitelik taşıması ve yalnız kendi yörelerini savunmaya çalışması Millî Mücadele açısından hangi ihtiyacı doğurmuştur?', 'Dağınık direnişi tek merkezden yönetecek bir birliğe', ['Azınlıklarla iş birliği yapılmasına', 'Padişahın yetkilerinin artırılmasına', 'İtilaf Devletleri\'nden borç alınmasına ve yardım istenmesine'], 'Cemiyetlerin bölgesel kalması güçlerin dağılmasına yol açıyordu; kongreler, Heyet-i Temsiliye ve sonrasında TBMM bu dağınıklığı tek merkezde birleştirme ihtiyacından doğmuştur.'),
  ('Mustafa Kemal\'in Samsun\'dan sonra uğradığı Havza\'da yayımladığı genelgede halka ne yapılması istenmiştir?', 'İşgalleri protesto eden mitingler düzenlenmesi', ['Her ilden üç delegenin Sivas\'a gönderilmesi', 'Askerlerin silahlarını teslim etmemesi için bildiri imzalanması', 'İstanbul hükümetiyle ilişkilerin kesilmesi'], 'Havza Genelgesi (28-29 Mayıs 1919) ile işgaller, özellikle İzmir\'in işgali, mitinglerle protesto edilmiş ve ulusal bilinç uyandırılmaya çalışılmıştır.'),
  ('Amasya Genelgesi\'nin "Vatanın bütünlüğü, milletin bağımsızlığı tehlikededir" maddesi ne anlama gelir?', 'Millî Mücadele\'nin gerekçesini ortaya koyar', ['Mücadelenin yöntemini belirler', 'Kongrenin toplanacağı yeri bildirir', 'Yeni bir hükümetin kurulduğunu halka duyurur'], 'Bu madde mücadelenin neden yapılması gerektiğini, yani gerekçesini açıklar; "milletin azim ve kararı" maddesi ise yöntemi gösterir.'),
  ('Amasya Genelgesi\'nde "İstanbul hükümeti üzerine aldığı sorumluluğun gereğini yerine getirememektedir" denmesi neyi göstermektedir?', 'İstanbul hükümetinin işlevsiz sayıldığını', ['Padişahın tahttan indirildiğini', 'Halifeliğin tümüyle kaldırılmak istendiğini', 'Mebusan Meclisi\'nin kapatıldığını'], 'Bu ifade İstanbul hükümetinin millî çıkarları koruyamadığını ve dolayısıyla yeni bir yönetim arayışının gerekli olduğunu belirtir; bu, ilk kez hükümete karşı bir tavır alındığını gösterir.'),
  ('Amasya Genelgesi\'ne göre Sivas\'ta toplanacak ulusal kongreye her sancaktan kaç delege gönderilecekti?', 'Üç', ['İki', 'Beş', 'Yedi'], 'Genelge, her sancaktan halkın güvenini kazanmış üç delegenin gizlice ve gecikmeden Sivas\'a gönderilmesini istemiştir.'),
  ('Mustafa Kemal hangi gelişmenin ardından askerlik mesleğinden istifa ederek mücadeleyi sivil olarak sürdürmeye karar vermiştir?', 'İstanbul\'a geri çağrılması ve görevinden alınması', ['Sivas Kongresi\'nde başkanlığa seçilmemesi ve küsmesi', 'Mebusan Meclisi\'ne milletvekili seçilmesi', 'Sevr Antlaşması\'nın imzalanması'], 'İstanbul hükümeti Mustafa Kemal\'i geri çağırıp görevden alınca, Erzurum\'a gelmeden önce 8-9 Temmuz 1919 gecesi askerlikten istifa etmiştir.'),
  ('Erzurum Kongresi bölgesel bir kongre olarak toplanmasına rağmen aldığı kararlar bakımından ulusal nitelik taşır. Bunun temel nedeni nedir?', 'Kararların tüm vatanı ilgilendirmesi', ['Bütün illerden delege katılması', 'Padişahın kongreyi onaylaması', 'Kararların İtilaf Devletleri\'nce tanınması'], 'Erzurum Kongresi doğu illerinin delegeleriyle toplanmıştır; ancak "Millî sınırlar içinde vatan bir bütündür" gibi kararları bütün ülkeyi kapsadığından ulusal nitelik kazanmıştır.'),
  ('Sivas Kongresi\'nde yayımlanması kararlaştırılan ve Millî Mücadele\'nin sesini duyuran gazete hangisidir?', 'İrade-i Milliye', ['Hâkimiyet-i Milliye', 'Anadolu\'da Yeni Gün', 'Tanin'], 'İrade-i Milliye gazetesi Sivas\'ta çıkarılmıştır. Hâkimiyet-i Milliye ise 1920\'de Ankara\'da yayımlanmaya başlamıştır.'),
  ('Sivas Kongresi\'nden sonra Damat Ferit hükümetinin istifa etmek zorunda kalması neyi gösterir?', 'Temsil Heyeti\'nin İstanbul hükümetine etki edebilecek güce ulaştığını', ['Padişahın Millî Mücadele\'yi açıkça ve resmen desteklediğini', 'İtilaf Devletleri\'nin Anadolu\'dan çekildiğini', 'Mebusan Meclisi\'nin kapatıldığını'], 'Temsil Heyeti, İstanbul ile haberleşmeyi kesince Damat Ferit hükümeti düşmüştür; bu, Anadolu\'daki hareketin siyasi bir güç hâline geldiğini gösterir.'),
  ('Damat Ferit hükümetinin düşmesinin ardından Temsil Heyeti ile İstanbul hükümeti arasında yapılan ve Temsil Heyeti\'nin İstanbul\'ca hukuken tanınması anlamına gelen görüşme hangisidir?', 'Amasya Görüşmeleri', ['Mudanya Görüşmeleri', 'Havza Görüşmeleri', 'Londra Görüşmeleri'], 'Ekim 1919\'da Mustafa Kemal ile Bahriye Nazırı Salih Paşa arasında Amasya\'da yapılan görüşmeler, İstanbul hükümetinin Temsil Heyeti\'ni muhatap kabul etmesi bakımından önemlidir.'),
  ('Heyet-i Temsiliye Aralık 1919\'da merkezini Sivas\'tan Ankara\'ya taşımıştır. Ankara\'nın seçilmesinde aşağıdakilerden hangisi etkili olmamıştır?', 'Osmanlı\'nın eski başkenti olması', ['Batı Cephesi\'ne yakın olması', 'Demiryolu bağlantısının bulunması', 'İstanbul ile haberleşmeye uygun konumda olması'], 'Ankara cepheye yakınlığı, demiryolu ve haberleşme olanakları ile güvenli konumu nedeniyle seçilmiştir. Osmanlı\'nın başkenti hiçbir zaman Ankara olmamıştır.'),
  ('Mustafa Kemal, Son Osmanlı Mebusan Meclisi\'nin İstanbul\'da toplanmasına başlangıçta karşı çıkmıştır. Bu tutumunun temel gerekçesi nedir?', 'İstanbul\'un işgal altında olması ve milletvekillerinin güvende olmayacağı', ['Meclisin padişah tarafından açılamayacak olması ve yetkisizliği', 'Milletvekillerinin çoğunun İttihatçı olmaması', 'Meclisin anayasada yer almaması'], 'Mustafa Kemal, işgal altındaki İstanbul\'da meclisin serbestçe çalışamayacağını düşünmüş ve meclisin Anadolu\'da toplanmasını istemiştir; nitekim meclis İstanbul\'un işgaliyle dağılmıştır.'),
  ('Misak-ı Millî\'de Kars, Ardahan ve Batum (Elviye-i Selase) için hangi yöntem öngörülmüştür?', 'Gerekirse halk oylamasına başvurulması', ['Doğrudan Rusya\'ya bırakılması', 'Milletler Cemiyeti denetimine verilmesi', 'Ermenistan\'a özerk bölge olarak verilmesi'], 'Misak-ı Millî\'ye göre Elviye-i Selase\'nin geleceği gerekirse halkın serbest oyuyla belirlenecekti; aynı yöntem Batı Trakya için de öngörülmüştür.'),
  ('Misak-ı Millî\'de kapitülasyonlarla ilgili hangi ilke benimsenmiştir?', 'Siyasi, adli ve mali gelişmeyi engelleyen kısıtlamalar kabul edilmeyecek', ['Kapitülasyonlar kademeli olarak on yıl içinde tamamen kaldırılacak', 'Kapitülasyonlar yalnız İngiltere için sürecek', 'Kapitülasyonlar Milletler Cemiyeti\'nce yeniden düzenlenecek'], 'Misak-ı Millî, millî ve iktisadi gelişmemizi engelleyen sınırlamaların kaldırılmasını öngörür; bu ilke Lozan\'da kapitülasyonların tümüyle kaldırılmasıyla gerçekleşmiştir.'),
  ('İtilaf Devletleri\'nin İstanbul\'u 16 Mart 1920\'de resmen işgal etmesinin doğrudan nedenlerinden biri aşağıdakilerden hangisidir?', 'Mebusan Meclisi\'nin Misak-ı Millî\'yi kabul etmesi', ['Sakarya Savaşı\'nın Türklerce kazanılması', 'Saltanatın kaldırılması', 'Lozan görüşmelerinin kesilmesi'], 'Misak-ı Millî\'nin kabulü İtilaf Devletleri\'nin paylaşım planlarına aykırıydı; bu nedenle İstanbul resmen işgal edilmiş ve meclis basılmıştır.'),
  ('İstanbul\'un işgalinin ardından Mustafa Kemal\'in Anadolu\'da yeni bir meclis toplanması için yaptığı çağrının dayandığı temel gerekçe nedir?', 'Meclisin dağıtılmasıyla ülkede yasal bir yasama organının kalmaması', ['Padişahın TBMM\'yi açmaya çağırması', 'İtilaf Devletleri\'nin Anadolu\'da yeniden genel seçim istemesi', 'Sevr\'in imzalanmış olması'], 'Mebusan Meclisi dağılınca millî iradeyi temsil eden bir meclis kalmamıştı; bu boşluğu doldurmak için olağanüstü yetkili bir meclis Ankara\'da toplanmıştır.'),
  ('I. TBMM\'de yürütme işlerini yapmak üzere meclis içinden seçilen bakanlardan oluşan kurul hangi adla anılır?', 'İcra Vekilleri Heyeti', ['Heyet-i Temsiliye', 'Meclis-i Vükela', 'Şura-yı Devlet'], 'İcra Vekilleri Heyeti, bakanların meclis tarafından tek tek seçildiği meclis hükümeti sisteminin yürütme organıdır.'),
  ('TBMM\'ye karşı çıkan ayaklanmaları bastırmak için çıkarılan Hıyanet-i Vataniye Kanunu ve kurulan İstiklal Mahkemeleri hangi amaca hizmet etmiştir?', 'İç düzeni sağlayıp meclisin otoritesini güçlendirmek', ['Azınlıklara yeni siyasi ve kültürel haklar tanımak', 'Halifeliği kaldırmak', 'Kapitülasyonları sona erdirmek'], 'Bu düzenlemeler isyancıları ve firarileri yargılayarak cephe gerisinde güvenliği sağlamış ve TBMM\'nin otoritesini kabul ettirmiştir.'),
  ('Aşağıdaki ayaklanmalardan hangisi doğrudan İstanbul hükümetinin kışkırtmasıyla çıkan isyanlara örnektir?', 'Anzavur Ayaklanması', ['Pontus Rum Ayaklanması', 'Koçgiri Ayaklanması', 'Çerkez Ethem Ayaklanması'], 'Ahmet Anzavur, padişah ve İstanbul hükümeti adına Balıkesir-Biga çevresinde ayaklanmıştır. Pontus azınlık kaynaklı, Çerkez Ethem ise Kuvâ-yı Milliye kaynaklıdır.'),
  ('TBMM\'ye karşı çıkan isyanların Millî Mücadele üzerindeki en önemli olumsuz etkisi aşağıdakilerden hangisidir?', 'Düşmana karşı kullanılacak gücün iç cephede harcanması', ['Saltanatın beklenenden çok önce kaldırılması', 'Mudanya\'nın ertelenmesi', 'Kongrelerin yapılamaması'], 'İsyanların bastırılması için birlikler cepheden çekilmek zorunda kalmış; bu da Yunan ilerleyişini kolaylaştırmıştır.'),
  ('Sevr Antlaşması hukuken yürürlüğe girmemiştir. Bunun temel nedeni aşağıdakilerden hangisidir?', 'Osmanlı Mebusan Meclisi\'nce onaylanmamış olması', ['Yunanistan\'ın antlaşmayı kendi meclisinde reddetmesi', 'ABD\'nin antlaşmayı veto etmesi', 'Padişahın imzayı geri çekmesi'], 'Mebusan Meclisi dağıtılmış olduğundan Sevr onaylanamamış ve hukuken geçerlilik kazanmamıştır. TBMM ise antlaşmayı imzalayanları vatan haini saymıştır.'),
  ('Sevr Antlaşması\'nda Boğazlar için nasıl bir yönetim öngörülmüştü?', 'Bayrağı ve bütçesi olan uluslararası bir komisyon yönetimi', ['Türk egemenliğinde ancak silahsızlandırılmış bir bölge', 'Yalnız İngiliz donanmasına açık bir bölge', 'Rusya ile Türkiye\'nin ortak denetimi'], 'Sevr\'e göre Boğazlar, kendine ait bayrağı ve bütçesi bulunan uluslararası bir komisyonca yönetilecekti; Türk temsilcisi bile komisyona ancak sonradan alınabilecekti.'),
  ('Sevr Antlaşması\'nın "ölü doğmuş bir antlaşma" olarak nitelendirilmesi aşağıdakilerden hangisiyle açıklanabilir?', 'Hiçbir zaman uygulanamaması ve yerini Lozan\'a bırakması', ['İmzalandığı gün feshedilmesi', 'Osmanlı heyetinin imzadan kaçınması', 'Yalnızca birkaç gün yürürlükte kalıp sonra feshedilmesi'], 'Sevr imzalanmış ama onaylanmamış, Millî Mücadele\'nin zaferiyle uygulanamamış ve Lozan ile geçersiz hâle gelmiştir.'),
  ('Gümrü Antlaşması\'nın Türk diplomasi tarihi bakımından önemi nedir?', 'TBMM\'nin uluslararası alanda imzaladığı ilk antlaşma olması', ['TBMM\'nin bir Avrupa devletiyle imzaladığı ilk ticaret antlaşması olması', 'Kapitülasyonları kaldıran ilk belge olması', 'Boğazların statüsünü belirleyen ilk antlaşma olması'], 'Ermenistan ile imzalanan Gümrü Antlaşması, TBMM\'nin askerî ve siyasi bir başarı olarak imzaladığı ilk uluslararası antlaşmadır.'),
  ('Güney Cephesi\'nde düzenli ordu yerine halkın Kuvâ-yı Milliye ile mücadele etmesinin temel nedeni nedir?', 'Düzenli ordunun Batı ve Doğu cephelerinde bulunması', ['Fransızların düzenli orduyla savaşmayı reddetmesi', 'Bölgede hiç askerî birlik bulunmaması gerektiğine dair antlaşma', 'Halkın düzenli orduya katılmayı istememesi'], 'Düzenli ordu başka cephelerle uğraştığından Antep, Maraş ve Urfa\'da Fransız ve Ermenilere karşı mücadeleyi büyük ölçüde halk yürütmüştür.'),
  ('Maraş\'ın Fransız işgaline karşı direnişi hangi olayla başlamıştır?', 'Sütçü İmam\'ın bir Türk kadınına saldıran askerlere karşı çıkması', ['Şahin Bey\'in bir Fransız karakolunu basması', 'Ali Saip Bey\'in Urfa\'da Fransızlara karşı isyan başlatması', 'Kara Fatma\'nın Maraş kalesine bayrak asması'], 'Sütçü İmam\'ın, Türk kadınlarına saldıran Fransız işbirlikçisi askerlere ateş açması Maraş direnişinin fitilini ateşlemiştir.'),
  ('I. İnönü zaferinden sonra İtilaf Devletleri hangi gelişmeyle TBMM\'yi ilk kez dolaylı olarak muhatap kabul etmiştir?', 'Londra Konferansı\'na TBMM temsilcilerini de çağırmasıyla', ['Ankara\'ya resmî olarak büyükelçi atamasıyla', 'Mudanya\'da ateşkes imzalamasıyla', 'Sevr\'i resmen iptal etmesiyle'], 'Şubat-Mart 1921\'deki Londra Konferansı\'na İstanbul hükümeti ile birlikte TBMM heyeti de davet edilmiş; bu, Ankara\'nın varlığının fiilen kabulü anlamına gelmiştir.'),
  ('Londra Konferansı\'nda TBMM heyetinin İstanbul heyetinden ayrı olarak konuşma hakkı istemesinin altında yatan amaç nedir?', 'Milleti temsil edenin TBMM olduğunu göstermek', ['İstanbul heyetiyle ortak bir tutum geliştirmek', 'Konferansı tümüyle ertelemek', 'Sevr\'in bazı maddelerini kabul ettirmek'], 'TBMM heyeti, İstanbul heyetinin sözcüsü Tevfik Paşa\'nın sözü Ankara\'ya bırakmasıyla Misak-ı Millî\'yi uluslararası platformda duyurma fırsatı bulmuştur.'),
  ('Kütahya-Eskişehir Muharebeleri\'nde yenilen Türk ordusunun Sakarya\'nın doğusuna çekilmesine kim karar vermiştir ve gerekçesi nedir?', 'Mustafa Kemal; orduyu korumak ve zaman kazanmak', ['İsmet Paşa; Ankara\'yı Yunanlılara teslim etmek', 'Fevzi Paşa; İngiltere ile hemen barış imzalamak', 'Kâzım Karabekir; Doğu Cephesi\'ni güçlendirmek'], 'Mustafa Kemal, ordunun yok olmasını önlemek ve yeniden toparlanması için Sakarya\'nın doğusuna çekilme kararı vermiştir; bu karar mecliste sert tartışmalara yol açmıştır.'),
  ('Tekâlif-i Milliye Emirleri\'ne göre halktan aşağıdakilerden hangisi istenmemiştir?', 'Her ailenin bir askerini doğrudan Doğu Cephesi\'ne göndermesi', ['Her evden bir kat çamaşır verilmesi', 'Mevcut erzakın yüzde kırkına el konulması', 'Taşıt araçlarıyla ayda bir kez ücretsiz taşıma yapılması'], 'Tekâlif-i Milliye ile çamaşır, erzak, hayvan, taşıt ve silah gibi kaynaklar orduya aktarılmıştır; ailelerden belirli bir cepheye asker göndermeleri istenmemiştir.'),
  ('Tekâlif-i Milliye Emirleri\'nin uygulanması hangi topyekûn mücadele anlayışının örneğidir?', 'Cephe ile cephe gerisinin birlikte seferber edilmesi', ['Savaşın yalnız profesyonel askerlerce yürütülmesi', 'Dış borçla savaş finansmanı sağlanması', 'Savaşın yalnızca diplomasiyle kazanılması'], 'Halkın erzakından taşıtına kadar kaynaklarını orduya vermesi, millet ve ordunun birlikte savaştığı topyekûn mücadeleyi gösterir.'),
  ('Sakarya Meydan Muharebesi\'nin Türk tarihi açısından önemi aşağıdakilerden hangisiyle en iyi açıklanır?', '1683\'ten beri süren geri çekilmenin durdurulması', ['Lozan Antlaşması\'nın imzalanmasını doğrudan sağlaması', 'Saltanatın kaldırılmasına doğrudan yol açması', 'Doğu Cephesi\'ni kapatması'], 'Sakarya zaferiyle II. Viyana Kuşatması\'ndan beri süren Türk geri çekilişi sona ermiş ve Türk ordusu savunmadan taarruza geçme imkânı bulmuştur.'),
  ('TBMM\'nin Sovyet Rusya ile 16 Mart 1921\'de imzaladığı Moskova Antlaşması\'nın önemi nedir?', 'TBMM\'yi tanıyan ilk büyük devletle yapılmış antlaşma olması', ['Boğazları Rusya\'ya bırakması', 'Kapitülasyonları Rusya lehine sürdürmesi ve genişletmesi', 'Batum\'u Türkiye\'ye vermesi'], 'Moskova Antlaşması ile Sovyet Rusya TBMM\'yi tanımış, Misak-ı Millî\'yi kabul etmiş ve kapitülasyonları geçersiz saymıştır; Batum Gürcistan\'a bırakılmıştır.'),
  ('Moskova Antlaşması\'nda Misak-ı Millî\'den verilen bir taviz olarak hangi şehir Gürcistan\'a bırakılmıştır?', 'Batum', ['Kars', 'Ardahan', 'Artvin'], 'Moskova Antlaşması\'yla Batum, liman olarak Türkiye\'ye bazı ticari kolaylıklar tanınmak şartıyla Gürcistan\'a bırakılmıştır. Bu, Misak-ı Millî\'den verilen ilk tavizdir.'),
  ('Ekim 1921\'de imzalanan Kars Antlaşması\'nın tarafları kimlerdir?', 'TBMM ile Gürcistan, Ermenistan ve Azerbaycan Sovyet cumhuriyetleri', ['TBMM ile Fransa, İngiltere, İtalya ve Yunanistan krallığı', 'TBMM ile Yunanistan ve Bulgaristan', 'TBMM ile İran ve Afganistan'], 'Kars Antlaşması, Moskova Antlaşması\'nın Kafkas cumhuriyetleriyle yeniden onaylanması niteliğinde olup doğu sınırını bugünkü şekline büyük ölçüde getirmiştir.'),
  ('Fransa\'nın 1921 Ankara Antlaşması ile TBMM\'yi tanıması İtilaf cephesi açısından ne anlama gelir?', 'İtilaf Devletleri arasındaki birliğin bozulması', ['Sevr\'in Fransa tarafından onaylanması', 'İngiltere ile Fransa\'nın ortak savaş kararı alması', 'Fransa\'nın Yunanistan\'a asker göndermesi'], 'Bir İtilaf devletinin TBMM ile ayrı antlaşma yapması, İtilaf bloğunun dağıldığını ve Sevr\'in uygulanamayacağını gösteren önemli bir gelişmedir.'),
  ('Mustafa Kemal\'in "Ordular, ilk hedefiniz Akdeniz\'dir. İleri!" emri hangi gelişmeden sonra verilmiştir?', 'Başkomutan Meydan Muharebesi\'nin kazanılması', ['İzmir\'in Türk ordusunca kurtarılması', 'Mudanya Ateşkesi\'nin imzalanması', 'Sakarya Muharebesi\'nin başlaması'], '30 Ağustos\'taki zaferden sonra 1 Eylül 1922\'de verilen bu emirle Türk ordusu kaçan Yunan birliklerini İzmir\'e kadar takip etmiştir.'),
  ('Mudanya Ateşkesi ile Doğu Trakya\'nın savaş yapılmadan Türkiye\'ye bırakılması neyi göstermektedir?', 'Askerî başarının diplomatik kazanca dönüştürüldüğünü', ['Türkiye\'nin Batı Trakya üzerindeki haklarından vazgeçmediğini', 'Sevr\'in kısmen uygulandığını', 'İngiltere\'nin Yunanistan\'ı desteklemeyi sürdürdüğünü'], 'Doğu Trakya\'nın Meriç\'e kadar savaşsız alınması, Büyük Taarruz\'un kazandığı üstünlüğün masada kalıcı hâle getirildiğini gösterir.'),
  ('Lozan Konferansı\'na hem TBMM\'nin hem de İstanbul hükümetinin çağrılması hangi gelişmeyi hızlandırmıştır?', 'Saltanatın kaldırılmasını', ['Cumhuriyetin ilan edilmesini ve başkentin belirlenmesini', 'Halifeliğin kaldırılmasını ve şeriye mahkemelerinin kapatılmasını', 'Çok partili hayata geçilmesini ve seçim yasasının değişmesini'], 'İtilaf Devletleri\'nin iki ayrı hükümeti davet etmesi ikiliği sona erdirme ihtiyacını doğurmuş ve TBMM 1 Kasım 1922\'de saltanatı kaldırmıştır.'),
  ('Saltanatın kaldırılmasıyla halifeliğin ayrı tutulması ve Abdülmecid Efendi\'nin halife seçilmesi aşağıdakilerden hangisini gösterir?', 'İnkılapların aşamalı olarak gerçekleştirildiğini', ['Laikliğin tamamen gerçekleştiğini', 'Cumhuriyetin önceden ilan edildiğini', 'Osmanlı hanedanının yönetimde etkisini sürdürdüğünü'], 'Saltanat ile halifeliğin aynı anda kaldırılmaması, toplumun hazır olmadığı adımların zamana yayıldığı aşamalı inkılap anlayışının örneğidir.'),
  ('Lozan Konferansı\'nın kesintiye uğramasına yol açan en önemli konu hangisidir?', 'Kapitülasyonlar', ['Batı Trakya\'nın statüsü', 'Ermeni yurdu talebi', 'Ege adalarının silahsızlandırılması'], 'İtilaf Devletleri\'nin kapitülasyonların sürmesinde ısrar etmesi ve Türk heyetinin bunu kesinlikle reddetmesi nedeniyle görüşmeler Şubat 1923\'te kesilmiştir.'),
  ('Lozan Antlaşması\'na göre Osmanlı borçları konusunda hangi çözüm benimsenmiştir?', 'Borçlar Osmanlı\'dan ayrılan devletler arasında paylaştırılmıştır', ['Borçların tamamı silinmiştir', 'Borçların bütünü yeni kurulan Türkiye\'ye yüklenmiştir', 'Borçlar İngiltere tarafından üstlenilmiştir'], 'Osmanlı borçları, Osmanlı\'dan ayrılan devletler arasında paylaştırılmış; Türkiye\'ye düşen pay taksitlerle ödenmiştir. Düyun-ı Umumiye de kaldırılmıştır.'),
  ('Lozan Antlaşması\'nda Boğazlar konusunda Türkiye açısından eksik kalan yön nedir?', 'Boğazların bir uluslararası komisyon denetiminde bırakılması', ['Boğazların İngiliz yönetimine verilmesi', 'Boğazlarda Türk ticaret gemilerinin geçişinin yasaklanması', 'Boğazların Yunanistan ile ortak yönetilmesi'], 'Lozan\'da Boğazların iki yakası silahsızlandırılmış ve başkanı Türk olan uluslararası bir komisyona bırakılmıştır. Bu eksiklik 1936 Montrö Sözleşmesi ile giderilmiştir.'),
  ('Lozan Antlaşması\'nda Gökçeada ve Bozcaada ile ilgili kararı hangisi doğru verir?', 'Türkiye\'ye bırakılmıştır', ['Yunanistan\'a bırakılmıştır', 'İtalya\'ya bırakılmıştır', 'Uluslararası yönetime verilmiştir'], 'Lozan\'la Çanakkale Boğazı\'nın güvenliği açısından önemli olan Gökçeada (İmroz) ve Bozcaada Türkiye\'de kalmış; diğer Ege adalarının çoğu Yunanistan\'a bırakılmıştır.'),
  ('Lozan Antlaşması\'nda Türkiye\'nin yabancı okullarla ilgili tutumu aşağıdakilerden hangisidir?', 'Türk yasalarına uymak şartıyla faaliyet gösterebilecekleri', ['Tamamının hemen kapatılacağı', 'Yalnızca elçiliklerin denetiminde açık kalabilecekleri', 'Milletler Cemiyeti\'nin gözetimine bırakılacakları'], 'Yabancı okullar ve azınlık okulları, Türk hükümetinin koyduğu yasalara uymak şartıyla eğitimlerini sürdürebilecekti.'),
  ('29 Ekim 1923\'te Cumhuriyetin ilan edilmesine yol açan bunalım aşağıdakilerden hangisidir?', 'Hükümetin istifasından sonra yenisinin kurulamaması', ['Halifenin TBMM\'yi kapatmaya ve dağıtmaya çalışması', 'Musul\'un İngiltere\'ye bırakılması', 'Lozan\'ın onaylanmaması'], 'Ekim 1923\'te Fethi Okyar hükümeti istifa edince meclis hükümeti sistemi içinde yeni bakanlar kurulu oluşturulamamış; bu bunalım Cumhuriyetin ilanıyla aşılmıştır.'),
  ('Cumhuriyetin ilanıyla devlet başkanlığı sorunu çözülmüş ve rejimin adı konmuştur. Aşağıdakilerden hangisi Cumhuriyetin ilanının doğrudan sonuçlarından biri değildir?', 'Kadınlara seçme ve seçilme hakkının tanınması', ['Devletin yönetim biçiminin belirlenmesi ve adının konması', 'Kabine sisteminin benimsenmesi', 'Devlet başkanı makamının oluşması'], 'Cumhuriyetin ilanıyla rejimin adı, devlet başkanlığı ve kabine sistemi belirlenmiştir. Kadınlara milletvekili seçme ve seçilme hakkı ise 1934\'te tanınmıştır.'),
  ('Cumhuriyetin ilanına muhalefet edenlerin öne sürdüğü eleştirilerden biri aşağıdakilerden hangisidir?', 'Kararın aceleyle ve danışılmadan alındığı', ['Cumhuriyetin saltanatı geri getireceği', 'Ankara\'nın başkent olmaması gerektiği', 'Lozan\'ın yeniden müzakere edilmesi gerektiği'], 'Rauf Orbay, Kâzım Karabekir gibi bazı isimler kararın aceleyle alındığını ve kendilerine danışılmadığını ileri sürmüştür; bu muhalefet daha sonra Terakkiperver Cumhuriyet Fırkası\'nın kurulmasına uzanmıştır.'),
  ('Şer\'iye ve Evkaf Vekâleti kaldırıldığında yerine kurulan iki kurum hangileridir?', 'Diyanet İşleri ve Vakıflar Genel Müdürlüğü', ['Millî Eğitim Bakanlığı ve Türk Tarih Kurumu', 'Danıştay ve Yargıtay', 'Halkevleri ve Köy Enstitüleri'], 'Din işlerinin yürütülmesi için Diyanet İşleri Başkanlığı, vakıfların yönetimi için Vakıflar Genel Müdürlüğü kurulmuştur.'),
  ('Tevhid-i Tedrisat Kanunu ile hangi uygulamaya son verilmiştir?', 'Medrese ve mektep olarak bölünmüş eğitim yapısına', ['Kadınların öğretmen olarak çalışmasına ve okul açmasına', 'Yabancı dil öğretimine', 'Zorunlu ilköğretime'], 'Bu kanunla bütün eğitim kurumları Maarif Vekâleti\'ne bağlanmış, eğitimdeki ikilik sona erdirilmiş ve medreseler kapatılmıştır.'),
  ('1921 Teşkilât-ı Esasiye Kanunu\'nun en belirgin özelliği aşağıdakilerden hangisidir?', 'Egemenliğin kayıtsız şartsız millete ait olduğunu ilk kez belirtmesi', ['Cumhuriyeti devletin yönetim biçimi olarak açıkça tanımlaması', 'Laikliği anayasaya eklemesi', 'Kadınlara seçme hakkı tanıması'], '1921 Anayasası, "Hâkimiyet bilâ kayd ü şart milletindir" ilkesini koyarak egemenliğin millete ait olduğunu belirten ilk anayasadır.'),
  ('1924 Anayasası, yasama ve yürütme yetkisini TBMM\'de toplarken yürütmeyi meclis adına kimin kullanacağını belirtmiştir?', 'Cumhurbaşkanı ve Bakanlar Kurulu', ['Başbakan ve Danıştay', 'Meclis başkanı ve Yargıtay', 'Genelkurmay Başkanı ve Millî Güvenlik Kurulu'], '1924 Anayasası\'na göre yasama yetkisi TBMM\'de, yürütme yetkisi ise meclis adına cumhurbaşkanı ve onun atadığı başbakan ile bakanlar kurulundaydı.'),
  ('Serbest Cumhuriyet Fırkası 1930\'da hangi amaçla ve kimin isteğiyle kurulmuştur?', 'Meclise denetim getirmek için Atatürk\'ün isteğiyle', ['Lozan\'ı yeniden müzakere etmek için İsmet Paşa\'nın isteğiyle', 'Halifeliği geri getirmek için muhaliflerin isteğiyle', 'Devletçiliği anayasaya koymak için Celal Bayar\'ın isteğiyle'], 'Atatürk, tek parti yönetiminin yarattığı denetimsizliği gidermek ve 1929 bunalımının sıkıntılarını tartışmaya açmak amacıyla Fethi Okyar\'dan yeni bir parti kurmasını istemiştir.'),
  ('Serbest Cumhuriyet Fırkası\'nın kısa sürede kendini kapatmasının nedeni aşağıdakilerden hangisidir?', 'İnkılap karşıtlarının partinin etrafında toplanması', ['Lozan Antlaşması\'na karşı çıkması', 'Ekonomik bunalımın sona ermesi', 'Atatürk\'ün partiye üye olmasının yasalarca yasaklanması'], 'Parti, özellikle İzmir mitingi sonrasında rejim karşıtlarının yoğun ilgisini görmüş; Fethi Okyar, Atatürk\'e karşı bir mücadeleye dönüşmesini istemediği için partiyi feshetmiştir.'),
  ('Şeyh Said İsyanı\'nın dış politikaya en önemli etkisi aşağıdakilerden hangisidir?', 'Musul görüşmelerinde Türkiye\'nin elini zayıflatması', ['Hatay\'ın Türkiye\'ye katılmasını beklenenden hızlandırması', 'Montrö Sözleşmesi\'nin imzalanmasını sağlaması', 'Balkan Antantı\'nın kurulmasına yol açması'], 'İsyan, Musul sorununun sürdüğü dönemde çıkmış ve Türkiye\'nin bölgede askerî baskı uygulamasını zorlaştırarak İngiltere\'nin işine yaramıştır.'),
  ('Menemen Olayı\'nın Serbest Cumhuriyet Fırkası\'nın kapanmasından kısa süre sonra yaşanması nasıl yorumlanmıştır?', 'İnkılap karşıtı hareketlerin hâlâ güçlü olduğunun işareti olarak', ['Halkın çok partili hayattan tümüyle ve kesin biçimde vazgeçtiğinin kanıtı olarak', 'Ordunun yönetime el koymak istediğinin belirtisi olarak', 'Dış güçlerin Türkiye\'ye savaş açtığının göstergesi olarak'], 'Menemen Olayı, gerici akımların sürdüğünü göstermiş ve inkılapların korunması için daha kararlı adımlar atılmasına yol açmıştır.'),
  ('Türk Medeni Kanunu\'nun kabulüyle aşağıdakilerden hangisi gerçekleşmemiştir?', 'Kadınlara milletvekili seçme hakkı verilmesi', ['Resmî nikâhın bütün evliliklerde zorunlu hâle gelmesi', 'Tek eşle evliliğin esas kabul edilmesi', 'Mirasta kadın ile erkeğin eşit sayılması'], 'Medeni Kanun aile hukukunda kadın-erkek eşitliğini getirmiştir; siyasi haklar ise 1930, 1933 ve 1934 düzenlemeleriyle tanınmıştır.'),
  ('Osmanlı\'da hukuk birliğinin sağlanamamasının temel nedeni olarak aşağıdakilerden hangisi gösterilebilir?', 'Şer\'i ve örfi hukukun, cemaat mahkemelerinin ve kapitülasyonların bir arada bulunması', ['Osmanlı\'da hiçbir dönemde yazılı bir kanun ya da kanunname bulunmaması ve hukukun sözlü olması', 'Mahkemelerin yalnızca İstanbul\'da toplanması', 'Kadıların atanmasının yasaklanması'], 'Farklı hukuk sistemleri ve yabancılara tanınan ayrıcalıklar hukuk birliğini engelliyordu; Cumhuriyet döneminde laik ve tek tip bir hukuk sistemi kurulmuştur.'),
  ('Mecelle\'nin yürürlükten kalkması hangi gelişmeyle olmuştur?', 'Türk Medeni Kanunu\'nun yürürlüğe girmesi', ['Halifeliğin kaldırılması ve hanedanın sürgünü', 'Saltanatın kaldırılması ve Ankara\'nın başkent olması', 'Harf İnkılabı ve Millet Mektepleri\'nin açılması'], 'Ahmet Cevdet Paşa başkanlığında hazırlanan Mecelle, 1926\'da Türk Medeni Kanunu\'nun yürürlüğe girmesiyle uygulamadan kalkmıştır.'),
  ('1931\'de kurulan Türk Tarih Kurumu ile 1932\'de kurulan Türk Dil Kurumu\'nun ortak amacı aşağıdakilerden hangisidir?', 'Millî kültürün bilimsel temellerde araştırılması', ['Dinî eğitimin yaygınlaştırılması', 'Yabancı okulların denetlenmesi', 'Ekonomik kalkınma planlarının hazırlanması ve uygulanması'], 'Bu iki kurum, Türk tarihini ve dilini bilimsel yöntemlerle araştırarak millî bilinci güçlendirmeyi amaçlamıştır; bu amaç milliyetçilik ilkesiyle ilgilidir.'),
  ('Halkevleri 1932\'de hangi amaçla açılmıştır?', 'İnkılapları halka benimsetmek ve kültürü yaygınlaştırmak', ['Askerlik çağındaki gençleri eğitmek', 'Köylere tarım makineleri dağıtmak', 'Muhalefet partilerinin yurt genelinde örgütlenmesini sağlamak'], 'Halkevleri dil, edebiyat, güzel sanatlar, spor ve köycülük gibi şubeleriyle inkılapları halka yaymak ve halkı eğitmek için kurulmuştur.'),
  ('Bir öğretmen, Cumhuriyet döneminde Türk tarihini Osmanlı ile sınırlamayıp Orta Asya\'dan başlatan ve Türklerin dünya uygarlığına katkısını vurgulayan görüşü anlatmaktadır. Öğretmenin söz ettiği görüş hangisidir?', 'Türk Tarih Tezi', ['Güneş Dil Teorisi', 'Tanzimatçılık', 'Turancılık'], 'Türk Tarih Tezi, Türk tarihinin Osmanlı\'dan ibaret olmadığını ve Türklerin köklü bir uygarlık mirasına sahip olduğunu ileri sürer.'),
  ('Atatürk\'ün şapka ve kıyafet devrimini halka tanıtmak için 1925\'te yaptığı gezinin merkezi hangi ildir?', 'Kastamonu', ['Samsun ve Havza', 'Sivas', 'Bursa'], 'Atatürk Ağustos 1925\'te Kastamonu ve İnebolu\'da yaptığı konuşmalarda şapkayı ve çağdaş kıyafeti tanıtmıştır.'),
  ('Soyadı Kanunu 1934\'te kabul edilmiştir. Aynı yıl kabul edilen başka bir kanunla hangi uygulamaya son verilmiştir?', 'Ağa, hacı, hafız, efendi, paşa gibi unvanların kullanımına', ['Hicri ve Rumi takvimin kullanımına', 'Arap harfleriyle yazılan bütün tabela ve levhalara', 'Yerel ağırlık birimlerinin kullanımına'], '26 Kasım 1934\'te çıkarılan kanunla lakap ve unvanlar kaldırılmış; böylece eşitlik ve halkçılık anlayışı güçlendirilmiştir.'),
  ('1925\'te uluslararası saat ve takvimin, 1931\'de ise metre ve kilogramın kabul edilmesi hangi amaca yöneliktir?', 'Dünyayla ekonomik ve sosyal ilişkilerin kolaylaştırılması', ['Dinî bayramların kaldırılması', 'Askerî harcamaların ve borçların azaltılması', 'Kırsal nüfusun kentlere taşınması'], 'Ölçü, tartı ve zaman birimlerinin uluslararası standartlara uyarlanması ticarette ve günlük hayatta karışıklığı gidermiş, Batı ile ilişkileri kolaylaştırmıştır.'),
  ('Türk kadınına siyasi haklar aşamalı olarak verilmiştir. Bu hakların tanınma sırası aşağıdakilerin hangisinde doğru verilmiştir?', 'Belediye seçimleri, muhtarlık seçimleri, milletvekilliği seçimleri', ['Milletvekilliği seçimleri, belediye seçimleri, muhtarlık seçimleri', 'Muhtarlık seçimleri, milletvekilliği seçimleri, belediye seçimleri', 'Belediye seçimleri, milletvekilliği seçimleri, muhtarlık ve ihtiyar heyeti seçimleri'], 'Kadınlar 1930\'da belediye, 1933\'te muhtarlık ve ihtiyar heyeti, 1934\'te milletvekili seçme ve seçilme hakkı kazanmıştır.'),
  ('1923\'te toplanan İzmir İktisat Kongresi\'nin önemi aşağıdakilerden hangisiyle en iyi açıklanır?', 'Lozan görüşmeleri sürerken ekonomik bağımsızlık kararlılığını göstermesi', ['Devletçilik ilkesinin doğrudan anayasaya girmesini sağlaması ve uygulatması', 'Birinci Beş Yıllık Sanayi Planı\'nı hazırlaması', 'Merkez Bankası\'nın kurulmasına karar vermesi'], 'Lozan\'a ara verildiği sırada toplanan kongre, Türkiye\'nin siyasi bağımsızlığı ekonomik bağımsızlıkla tamamlayacağını dünyaya göstermiştir.'),
  ('İzmir İktisat Kongresi\'ne hangi kesimler katılmıştır?', 'Çiftçi, tüccar, sanayici ve işçi temsilcileri', ['Yalnızca milletvekilleri ve bakanlar', 'Yalnızca yabancı yatırımcılar, bankacılar ve elçilik temsilcileri', 'Askerî komutanlar ve din adamları'], 'Kongreye çiftçi, tüccar, sanayici ve işçi grupları olmak üzere ekonominin farklı kesimlerinden yaklaşık 1135 delege katılmıştır.'),
  ('1926\'da kabul edilen Kabotaj Kanunu ile Türk karasularında hangi hak yalnızca Türk gemilerine tanınmıştır?', 'Limanlar arası taşımacılık', ['Balık avlama ve sünger çıkarma', 'Petrol arama ve çıkarma', 'Askerî tatbikat yapma'], 'Kabotaj Kanunu ile Türk limanları arasında yük ve yolcu taşıma hakkı Türk gemilerine verilmiş; kapitülasyon döneminden kalan yabancı ayrıcalığı sona ermiştir.'),
  ('1 Temmuz günü Türkiye\'de "Denizcilik ve Kabotaj Bayramı" olarak kutlanır. Bunun nedeni aşağıdakilerden hangisidir?', 'Türk limanları arası taşımayı Türk gemilerine bırakan kanunun yürürlüğe girmesi', ['Türk donanmasının bu tarihte kurulması', 'Montrö Boğazlar Sözleşmesi\'nin bu tarihte imzalanması ve onaylanması', 'İzmir\'in bu tarihte kurtarılması'], 'Kabotaj Kanunu 1 Temmuz 1926\'da yürürlüğe girmiştir; bu nedenle bu gün Denizcilik ve Kabotaj Bayramı olarak kutlanır.'),
  ('1927\'de çıkarılan Teşvik-i Sanayi Kanunu\'nun temel amacı nedir?', 'Özel sektörü sanayi yatırımlarına özendirmek', ['Tüm fabrikaları devletleştirmek', 'Yabancı şirketlerin Türkiye\'den çıkmasını sağlamak', 'Tarım ürünlerinin ihracatını yasaklamak'], 'Kanun, sanayi kuranlara arazi, vergi muafiyeti ve gümrük kolaylığı gibi teşvikler sağlayarak özel girişimi desteklemeyi amaçlamıştır.'),
  ('1929 Dünya Ekonomik Bunalımı\'nın Türkiye\'de devletçilik politikasına geçilmesine etkisi nasıl açıklanabilir?', 'Özel sermayenin yetersizliğinin bunalımla iyice ortaya çıkması', ['Bunalımın Türkiye\'nin bütün dış borçlarını tümüyle silmesi ve rahatlatması', 'Bunalımla birlikte yabancı yatırımların hızla artması', 'Bunalımın tarım ürünü fiyatlarını yükseltmesi'], 'Bunalım, tarım ürünü fiyatlarını düşürmüş ve dış ticareti daraltmıştır; özel girişimin sanayileşmeyi tek başına sağlayamayacağı anlaşılınca devlet ekonomide doğrudan rol üstlenmiştir.'),
  ('Türkiye Cumhuriyeti Merkez Bankası hangi yıl kurulmuştur?', '1930', ['1924', '1933', '1927'], 'Türkiye Cumhuriyet Merkez Bankası 1930\'da kurulmuş, 1931\'de faaliyete geçmiştir. 1924\'te ise Türkiye İş Bankası kurulmuştur.'),
  ('Aşağıdaki inkılaplardan hangisi doğrudan laiklik ilkesiyle ilişkilendirilemez?', 'Kabotaj Kanunu\'nun çıkarılması', ['Halifeliğin kaldırılması', 'Tevhid-i Tedrisat Kanunu\'nun kabulü', 'Tekke ve zaviyelerin kapatılması'], 'Kabotaj Kanunu ekonomik bağımsızlıkla ilgilidir; diğer üçü din ile devlet işlerinin ayrılmasına yönelik laik düzenlemelerdir.'),
  ('Bir ülkede ekonomik alanda özel girişimin yetersiz kaldığı yerlerde devletin yatırım yapması, ancak özel girişimin de korunması öngörülüyor. Bu yaklaşım Atatürk ilkelerinden hangisine en yakındır?', 'Devletçilik', ['Halkçılık', 'Laiklik', 'Cumhuriyetçilik'], 'Türk devletçiliği, özel girişimi ortadan kaldırmadan, onun yetersiz kaldığı alanlarda devletin ekonomiye girmesini öngören karma bir modeldir.'),
  ('Atatürk\'ün milliyetçilik anlayışının diğer bazı milliyetçilik türlerinden farkı aşağıdakilerden hangisidir?', 'Irkçılığı ve yayılmacılığı reddetmesi', ['Yalnızca dinî bağı esas alması', 'Başka milletlere üstünlük iddia etmesi', 'Sınırların genişletilmesini hedeflemesi'], 'Atatürk milliyetçiliği birleştirici, barışçı ve ülke bütünlüğüne dayalı olup ırkçılık, saldırganlık ve yayılmacılığı reddeder.'),
  ('Atatürk ilkelerini simgeleyen "altı ok" ilk olarak hangi kuruluşun amblemi olarak kullanılmıştır?', 'Cumhuriyet Halk Fırkası', ['Türk Ocakları', 'Halkevleri Genel Merkezi', 'Türk Tarih Kurumu'], 'Altı ok, 1931 kurultayında programına altı ilkeyi alan Cumhuriyet Halk Fırkası\'nın amblemi olmuştur.'),
  ('Musul sorunu 1926\'da hangi antlaşmayla sonuçlanmıştır ve Türkiye\'ye ne verilmiştir?', 'Ankara Antlaşması; 25 yıl süreyle petrol gelirinin %10\'u', ['Lozan Antlaşması; Musul\'un yarısı ve Kerkük şehri', 'Montrö Sözleşmesi; Boğazlarda tam egemenlik hakkı', 'Sadabad Paktı; İran\'ın Musul üzerindeki haklarından vazgeçmesi'], '5 Haziran 1926 Ankara Antlaşması ile Musul Irak\'a bırakılmış, Türkiye\'ye 25 yıl boyunca Musul petrol gelirlerinden %10 pay verilmesi kabul edilmiştir.'),
  ('Türkiye\'nin Milletler Cemiyeti\'ne üye olurken diğer devletlerden farklı olarak davet edilmesi neyi gösterir?', 'Türkiye\'nin uluslararası saygınlığının arttığını', ['Türkiye\'nin örgütün kurallarını kabul etmediğini', 'Türkiye\'nin manda yönetimi altında olduğunu', 'Türkiye\'nin Mihver Devletleri\'ne yakın durduğunu ve onlarla anlaştığını'], 'Türkiye 18 Temmuz 1932\'de Milletler Cemiyeti\'ne davet edilerek üye olmuştur; bu durum genç Cumhuriyet\'in barışçı dış politikasının takdir gördüğünü gösterir.'),
  ('1934\'te Türkiye, Yunanistan, Romanya ve Yugoslavya arasında kurulan Balkan Antantı\'nın temel amacı neydi?', 'Balkanlardaki sınırları İtalya ve Bulgaristan gibi revizyonist devletlere karşı korumak', ['Balkan ülkelerini tek bir federasyon çatısı altında birleştirmek ve ortak ordu kurmak', 'Sovyetler Birliği\'ne karşı askerî saldırı hazırlamak', 'Balkan ülkeleri arasında ortak bir para birimi oluşturmak'], 'Balkan Antantı, özellikle İtalya\'nın yayılmacılığına ve Bulgaristan\'ın sınır değişikliği isteklerine karşı bölgedeki mevcut sınırların korunmasını amaçlamıştır.'),
  ('Hatay sorununun gündeme gelmesi hangi gelişmeyle başlamıştır?', 'Fransa\'nın Suriye\'ye bağımsızlık vermeyi kabul etmesi', ['İngiltere\'nin Irak\'tan çekilmesi', 'İtalya\'nın Hatay\'ı işgal etmesi', 'Hatay halkının toplu olarak Fransız vatandaşlığına geçmesi'], '1936\'da Fransa Suriye\'ye bağımsızlık vereceğini açıklayınca, Türkiye Hatay\'ın da Suriye\'ye bırakılmasına karşı çıkmış ve sorunu Milletler Cemiyeti\'ne taşımıştır.'),
  ('Hatay\'ın Türkiye\'ye katılma sürecinin doğru sıralaması aşağıdakilerden hangisidir?', 'Bağımsız Hatay Devleti\'nin kurulması, ardından meclisin Türkiye\'ye katılma kararı', ['Doğrudan Türkiye\'ye katılma, ardından halk oylaması', 'Suriye\'ye bağlanma, ardından Lozan Antlaşması\'yla Türkiye\'ye geçiş ve halkoylaması', 'Fransa\'ya bağlanma, ardından Montrö ile Türkiye\'ye geçiş'], 'Hatay 1938\'de bağımsız bir devlet olmuş, Hatay Meclisi 29 Haziran 1939\'da Türkiye\'ye katılma kararı almıştır.'),
  ('1930\'da Türkiye ile Yunanistan arasında imzalanan Ankara Antlaşması\'nın önemi aşağıdakilerden hangisidir?', 'Mübadele ve mülkiyet sorunlarını çözerek iki ülkeyi yakınlaştırması', ['Ege adalarını Türkiye\'ye bırakması', 'Kıbrıs\'ı iki ülke arasında paylaştırması ve sınırları çizmesi ile ortak yönetim getirmesi', 'Batı Trakya\'yı Türkiye\'ye bağlaması'], '1930 Ankara Antlaşması mübadele sonrası mülkiyet anlaşmazlıklarını çözmüş; Atatürk ve Venizelos döneminde iki ülke ilişkileri belirgin biçimde düzelmiştir.'),
  ('Mustafa Kemal\'e "Kemal" adını kim vermiştir?', 'Matematik öğretmeni Mustafa Bey', ['Babası Ali Rıza Efendi', 'Harbiye\'den sınıf arkadaşı Ali Fuat', 'Annesi Zübeyde Hanım'], 'Selanik Askerî Rüştiyesi\'ndeki matematik öğretmeni Mustafa Bey, onu ayırt etmek ve başarısını takdir etmek için "Kemal" adını vermiştir.'),
  ('Mustafa Kemal\'in I. Dünya Savaşı\'nda Muş ve Bitlis\'i Ruslardan geri aldığı cephe hangisidir?', 'Kafkas Cephesi', ['Irak Cephesi', 'Suriye Cephesi', 'Galiçya Cephesi'], 'Mustafa Kemal 1916\'da 16. Kolordu komutanı olarak Kafkas Cephesi\'nde Muş ve Bitlis\'i geri almıştır.'),
  ('Atatürk\'ün 1936-1937 yıllarında yazdığı ve geometri terimlerinin Türkçe karşılıklarını içeren eserde türetilen kelimelerden biri aşağıdakilerden hangisidir?', 'Üçgen', ['Müselles', 'Murabba', 'Hatt-ı müstakim'], 'Atatürk\'ün Geometri kitabında müselles yerine üçgen, murabba yerine kare gibi terimler kullanılmıştır; diğer seçenekler eski Osmanlıca terimlerdir.'),
  ('Atatürk\'ün naaşı Anıtkabir\'e hangi yıl nakledilmiştir?', '1953', ['1944', '1960', '1948'], 'Anıtkabir\'in tamamlanmasının ardından Atatürk\'ün naaşı 10 Kasım 1953\'te Etnografya Müzesi\'ndeki geçici kabrinden Anıtkabir\'e nakledilmiştir.'),
  ('Mustafa Kemal\'in Trablusgarp Savaşı\'nda İtalyanlara karşı başarı kazandığı yer aşağıdakilerden hangisidir?', 'Tobruk', ['Kosova', 'Kırkkilise', 'Halep'], 'Mustafa Kemal 1911-1912 Trablusgarp Savaşı\'nda gönüllü olarak gitmiş ve Tobruk ile Derne\'de İtalyanlara karşı başarılar kazanmıştır.'),
  ('Mustafa Kemal\'in Harbiye\'den sonra kurmay subay olarak mezun olduğu okul hangisidir?', 'Harp Akademisi', ['Manastır Askerî İdadisi', 'Selanik Askerî Rüştiyesi', 'Mekteb-i Mülkiye'], 'Mustafa Kemal 1902\'de Harbiye\'yi, 1905\'te Harp Akademisi\'ni kurmay yüzbaşı olarak bitirmiştir.'),
  ('Türkiye\'nin Şubat 1945\'te Almanya ve Japonya\'ya savaş ilan etmesinin temel nedeni nedir?', 'Birleşmiş Milletler\'in kurucu toplantısına katılabilmek', ['Alman ordusunun Trakya\'ya girmesi', 'Japonya\'nın İstanbul\'u bombalaması', 'Sovyetlerin Türkiye\'yi doğrudan savaşa girmeye zorlaması'], 'Yalta\'da 1 Mart 1945\'e kadar Mihver\'e savaş ilan eden devletlerin San Francisco Konferansı\'na çağrılacağı kararlaştırılmıştı; Türkiye bu nedenle sembolik bir savaş ilanında bulunmuştur.'),
  ('1942\'de çıkarılan Varlık Vergisi\'nin en çok eleştirilen yönü aşağıdakilerden hangisidir?', 'Vergi miktarlarının özellikle gayrimüslimlere ağır biçimde uygulanması', ['Yalnızca köylülerden alınması', 'Hiçbir yaptırımının bulunmaması', 'Savaş sona erdikten sonra da yıllarca sürekli olarak uygulanması'], 'Savaş ekonomisinin yükünü karşılamak için çıkarılan Varlık Vergisi, gayrimüslim tüccarlara orantısız yüksek miktarlar biçilmesi ve ödeyemeyenlerin çalışma kamplarına gönderilmesi nedeniyle eleştirilmiştir.'),
  ('II. Dünya Savaşı yıllarında Türkiye\'de uygulanan Millî Korunma Kanunu ve ekmeğin karneye bağlanması neyi göstermektedir?', 'Savaş dışında kalınsa da ekonominin ağır biçimde etkilendiğini', ['Türkiye\'nin savaştan büyük ekonomik kazanç sağladığını ve zenginleştiğini', 'Tarımsal üretimin iki katına çıktığını', 'Dış ticaretin tümüyle serbest bırakıldığını'], 'Seferberlik nedeniyle iş gücünün azalması ve askerî harcamaların artması karaborsa ve kıtlığa yol açmış; devlet bu kanun ve karne uygulamasıyla ekonomiye müdahale etmiştir.'),
  ('Sovyetler Birliği\'nin 1945\'te Türkiye\'den Boğazlarda üs ve Kars-Ardahan\'ı istemesi Türk dış politikasında hangi sonuca yol açmıştır?', 'Türkiye\'nin Batı bloğuna yönelmesine', ['Türkiye\'nin Varşova Paktı\'na katılmasına', 'Türkiye\'nin Montrö\'den çekilmesine', 'Türkiye\'nin İran\'la birleşmesine'], 'Sovyet talepleri Türkiye\'yi güvenlik arayışına itmiş; Truman Doktrini, Marshall Planı ve sonunda NATO üyeliğiyle Türkiye Batı bloğunda yer almıştır.'),
  ('1946 seçimlerinin Türk demokrasi tarihindeki önemi ve en çok eleştirilen yönü birlikte düşünüldüğünde aşağıdakilerden hangisi doğrudur?', 'Çok partili ilk genel seçimdir; açık oy gizli sayım uygulanmıştır', ['Kadınların ilk kez oy kullandığı seçimdir; seçim sonradan iptal edilmiştir', 'İlk kez doğrudan cumhurbaşkanı seçilmiştir; katılım düşüktür', 'DP\'nin tek başına iktidar olduğu seçimdir; ordu müdahale etmiştir'], '1946 seçimi çok partili ilk genel seçimdir; ancak açık oy, gizli tasnif yöntemi nedeniyle güvenilirliği tartışılmıştır.'),
  ('1950 seçimlerinin gizli oy, açık sayım ilkesine göre yapılmasının önemi nedir?', 'Seçim güvenliğini artırarak sonucun meşruiyetini güçlendirmesi', ['Kadınların oy kullanmasını yasaklaması', 'Seçimlerin iki dereceli yapılmasını sağlaması ve seçmeni azaltması', 'Muhalefetin seçime katılmasını engellemesi'], '1950 seçimleri 1950 Seçim Kanunu\'yla gizli oy, açık sayım ve yargı denetimi altında yapılmış; bu, iktidarın barışçıl biçimde el değiştirmesini mümkün kılmıştır.'),
  ('DP iktidarının ilk yıllarında Türkiye\'nin NATO\'ya girme isteğini güçlendirmek için gerçekleştirdiği dış politika adımı hangisidir?', 'Kore Savaşı\'na asker göndermesi', ['Kıbrıs\'a askerî çıkarma yapması', 'Bağdat Paktı\'ndan çekilmesi', 'Süveyş Kanalı\'nı denetlemesi'], 'Türkiye 1950\'de BM kararı doğrultusunda Kore\'ye tugay göndermiş; bu adım 1952\'de NATO\'ya kabul edilmesini kolaylaştırmıştır.'),
  ('1950\'lerde Marshall yardımları ve tarımda makineleşme Türkiye\'de hangi toplumsal sonucu doğurmuştur?', 'Köyden kente göçün hızlanması', ['Kentlerden köylere geri göç yaşanması', 'Tarım nüfusunun hızla artması', 'Sanayinin tümüyle devletleştirilmesi'], 'Traktörün yaygınlaşmasıyla tarımda iş gücü ihtiyacı azalmış, açığa çıkan nüfus büyük kentlere göç etmiş ve gecekondulaşma başlamıştır.'),
  ('1955\'te Türkiye, Irak, İran, Pakistan ve İngiltere arasında kurulan ve sonradan CENTO adını alan ittifak hangisidir?', 'Bağdat Paktı', ['Sadabad Paktı', 'Balkan Paktı', 'Varşova Paktı'], 'Bağdat Paktı, Orta Doğu\'da Sovyet yayılmasına karşı kurulmuş; Irak\'ın 1959\'da ayrılmasıyla merkezi Ankara\'ya taşınmış ve adı CENTO olmuştur.'),
  ('1960 müdahalesinden sonra kurulan Yassıada mahkemesinde verilen idam kararları sonucunda idam edilen üç kişi kimdir?', 'Adnan Menderes, Fatin Rüştü Zorlu, Hasan Polatkan', ['Celal Bayar, Adnan Menderes, Refik Koraltan', 'Adnan Menderes, Fuat Köprülü ve Cumhurbaşkanı Celal Bayar', 'Fatin Rüştü Zorlu, Refik Koraltan, Samet Ağaoğlu'], 'Yassıada yargılamaları sonucunda 1961\'de Menderes, Zorlu ve Polatkan idam edilmiş; Celal Bayar\'ın idam cezası yaşı nedeniyle ömür boyu hapse çevrilmiştir.'),
  ('1961 Anayasası\'nın getirdiği yeniliklerden biri aşağıdakilerden hangisidir?', 'Anayasa Mahkemesi\'nin kurulması', ['Tek meclisli yapının benimsenmesi', 'Kadınlara seçme hakkının tanınması', 'Cumhurbaşkanının halk tarafından seçilmesi'], '1961 Anayasası Anayasa Mahkemesi\'ni kurmuş, iki meclisli (Millet Meclisi ve Cumhuriyet Senatosu) bir yapı getirmiş ve temel hakları genişletmiştir.'),
  ('1961 Anayasası\'nın özgürlükçü bir anayasa olarak nitelendirilmesinin nedeni aşağıdakilerden hangisidir?', 'Sendika, grev ve basın gibi hak ve özgürlükleri genişletmesi', ['Siyasi partileri yasaklaması', 'Yargı bağımsızlığını kaldırması', 'Üniversitelerin ve TRT\'nin özerkliğini tümüyle sona erdirmesi'], '1961 Anayasası sosyal hukuk devleti ilkesini benimsemiş; grev ve toplu sözleşme hakkı, üniversite ve TRT özerkliği gibi düzenlemelerle temel hakları genişletmiştir.'),
  ('12 Mart 1971\'de Genelkurmay Başkanı ve kuvvet komutanlarının hükümete verdiği muhtıra sonucunda istifa eden başbakan kimdir?', 'Süleyman Demirel', ['Bülent Ecevit', 'Nihat Erim', 'İsmet İnönü Paşa'], '12 Mart Muhtırası üzerine Süleyman Demirel istifa etmiş, ardından Nihat Erim başkanlığında partiler üstü bir hükümet kurulmuştur.'),
  ('1974 Kıbrıs Barış Harekâtı\'nın Türkiye tarafından gerekçesi aşağıdakilerden hangisidir?', 'Yunanistan destekli darbeyle adanın Yunanistan\'a bağlanma tehlikesi', ['Kıbrıs\'ın NATO\'dan ayrılmak istemesi', 'İngiltere\'nin adadaki üslerinden çekilmeyi kesin biçimde reddetmesi', 'Kıbrıs\'ın Sovyetler Birliği\'ne katılmak istemesi'], 'Temmuz 1974\'te Yunan cuntası destekli darbeyle Makarios devrilip Nikos Sampson getirilince, Türkiye 1960 Garanti Antlaşması\'na dayanarak 20 Temmuz\'da harekât başlatmıştır.'),
  ('Kıbrıs Barış Harekâtı\'nın ardından ABD\'nin Türkiye\'ye uyguladığı yaptırım hangisidir?', 'Silah ambargosu', ['Petrol ambargosu', 'Vize yasağı', 'Ticari boykot ile NATO\'dan çıkarma'], 'ABD Kongresi, harekâtta Amerikan silahlarının kullanıldığı gerekçesiyle 1975\'te Türkiye\'ye silah ambargosu uygulamış; ambargo 1978\'de kaldırılmıştır.'),
  ('1960\'ta kurulan Kıbrıs Cumhuriyeti\'nin garantör devletleri aşağıdakilerin hangisinde birlikte verilmiştir?', 'Türkiye, Yunanistan, İngiltere', ['Türkiye, Yunanistan, ABD', 'İngiltere, Fransa, Türkiye', 'Yunanistan, İngiltere, Sovyetler Birliği'], 'Zürih ve Londra antlaşmalarıyla kurulan Kıbrıs Cumhuriyeti\'nin bağımsızlığını Türkiye, Yunanistan ve İngiltere garanti etmiştir.'),
  ('24 Ocak 1980 kararlarıyla Türkiye ekonomisinde hangi yönde bir dönüşüm başlamıştır?', 'İthal ikameci modelden dışa açık serbest piyasa ekonomisine', ['Serbest piyasadan merkezi planlı ekonomiye', 'Sanayiden tarıma dayalı, ihracatı yasaklayan kapalı bir ekonomiye', 'Dış ticaretten tümüyle kapalı ekonomiye'], 'Turgut Özal\'ın hazırladığı 24 Ocak kararları ihracata dayalı büyümeyi, fiyat serbestisini ve dışa açılmayı hedefleyen bir yapısal dönüşümün başlangıcıdır.'),
  ('Türkiye, Avrupa Ekonomik Topluluğu ile ortaklık ilişkisini kuran Ankara Antlaşması\'nı hangi yıl imzalamıştır?', '1963', ['1959', '1987', '1970'], 'Türkiye 1959\'da AET\'ye başvurmuş, 1963\'te Ankara Antlaşması ile ortak üye olmuş, 1987\'de tam üyelik için başvurmuştur.'),
  ('Türkiye\'nin 1949\'da üye olduğu, insan haklarını ve demokrasiyi korumayı amaçlayan Avrupa örgütü hangisidir?', 'Avrupa Konseyi', ['Avrupa Ekonomik Topluluğu', 'Avrupa Kömür ve Çelik Topluluğu', 'Avrupa Serbest Ticaret Birliği'], 'Türkiye, 1949\'da kurulan Avrupa Konseyi\'ne aynı yıl katılmıştır; bu, Türkiye\'nin Batı ile bütünleşme sürecinin ilk adımlarından biridir.'),
  ('Türkiye 1947\'de Truman Doktrini kapsamında ABD yardımı almıştır. Bu yardımı Yunanistan ile birlikte alması neyi gösterir?', 'Her iki ülkenin de Sovyet tehdidi altında görülmesini', ['İki ülkenin birleşerek tek devlet olmasını ve ortak ordu kurmasını', 'Yunanistan\'ın Türkiye\'ye borç vermesini', 'ABD\'nin Ege adalarını satın almasını'], 'Truman Doktrini, Sovyet yayılmacılığına karşı Türkiye ve Yunanistan\'ı korumak amacıyla 1947\'de ilan edilmiş ve iki ülkeye askerî-ekonomik yardım öngörmüştür.'),
  ('ABD\'nin 1917\'de I. Dünya Savaşı\'na katılmasında etkili olan gelişmelerden biri aşağıdakilerden hangisidir?', 'Almanya\'nın sınırsız denizaltı savaşını başlatması', ['Japonya\'nın Pearl Harbor\'a saldırması', 'Rusya\'nın ABD\'ye savaş ilan etmesi', 'Osmanlı\'nın Panama Kanalı\'nı kapatması ve ticaret yollarını kesmesi'], 'Almanya\'nın tarafsız gemileri de batırdığı sınırsız denizaltı savaşı ve Zimmermann Telgrafı, ABD\'nin Nisan 1917\'de savaşa girmesine yol açmıştır.'),
  ('Versay Antlaşması\'nın (1919) Almanya\'ya getirdiği ağır koşulların uzun vadeli sonucu olarak aşağıdakilerden hangisi gösterilebilir?', 'Almanya\'da intikam duygusunun Nazizmin yükselişine zemin hazırlaması', ['Almanya\'nın hemen Milletler Cemiyeti\'nin lideri olması', 'Fransa ile Almanya\'nın kalıcı bir ittifak kurması', 'Almanya\'nın sömürgelerini Afrika ve Asya\'da genişletmesi ve güçlenmesi'], 'Toprak kayıpları, ağır savaş tazminatı ve ordunun sınırlandırılması Almanlarda büyük tepki doğurmuş; Hitler bu hoşnutsuzluğu kullanarak iktidara gelmiştir.'),
  ('I. Dünya Savaşı\'nın sonunda dağılan imparatorluklar arasında aşağıdakilerden hangisi yer almaz?', 'Britanya İmparatorluğu', ['Avusturya-Macaristan İmparatorluğu', 'Rus Çarlığı', 'Alman İmparatorluğu'], 'Savaş sonunda Alman, Avusturya-Macaristan, Rus ve Osmanlı imparatorlukları dağılmıştır; Britanya İmparatorluğu ise savaştan galip çıkmış ve sömürgelerini korumuştur.'),
  ('Bolşeviklerin "Barış, toprak, ekmek" sloganı halktan geniş destek görmüştür. Bu sloganın etkili olmasının temel nedeni nedir?', 'Savaştan bıkmış ve yoksullaşmış halkın taleplerini karşılaması', ['Çarlığın yeniden kurulmasını vaat etmesi', 'Rusya\'nın sömürgelerini Asya\'da genişletmeyi ve savaşı sürdürmeyi önermesi', 'Kiliseye geniş toprak verilmesini savunması'], 'Savaşın yıkımı, açlık ve toprak sorunu Rus halkını bezdirmişti; Bolşeviklerin savaştan çekilme ve toprak dağıtma vaadi bu nedenle karşılık bulmuştur.'),
  ('Lenin\'in 1921\'de ilan ettiği ve küçük ölçekli özel ticarete izin veren politika hangisidir?', 'Yeni Ekonomik Politika', ['Beş Yıllık Planlar ve kolektifleştirme', 'Savaş Komünizmi', 'Perestroyka'], 'İç savaş sonrasında ekonomiyi canlandırmak için ilan edilen NEP, sınırlı piyasa ekonomisine izin vermiştir; Stalin döneminde yerini beş yıllık planlara bırakmıştır.'),
  ('Sovyetler Birliği (SSCB) resmen hangi yıl kurulmuştur?', '1922', ['1917', '1918', '1924'], 'Sovyet Sosyalist Cumhuriyetler Birliği Aralık 1922\'de Rusya, Ukrayna, Beyaz Rusya ve Transkafkasya cumhuriyetlerinin birleşmesiyle kurulmuştur.'),
  ('Stalin döneminde tarımda uygulanan kolektifleştirme politikası neyi amaçlamıştır?', 'Özel çiftlikleri devlet denetimindeki ortak çiftliklerde birleştirmeyi', ['Toprağı köylülere bireysel ve miras bırakılabilir mülk olarak dağıtmayı', 'Tarımı tümüyle yabancı şirketlere bırakmayı', 'Tarım ürünlerinin ihracatını yasaklamayı ve sanayiyi geri plana itmeyi'], 'Kolektifleştirmeyle köylü toprakları kolhoz ve sovhozlarda birleştirilmiş; süreç kulakların tasfiyesine ve büyük kıtlıklara yol açmıştır.'),
  ('Büyük Buhran\'ın siyasi sonuçlarından biri olarak aşağıdakilerden hangisi gösterilebilir?', 'Bazı ülkelerde totaliter rejimlerin güç kazanması', ['Dünya genelinde serbest ticaretin hızla yaygınlaşması', 'Sömürgeciliğin tamamen sona ermesi', 'Milletler Cemiyeti\'nin güçlenmesi'], 'Ekonomik çöküş, işsizlik ve yoksulluk Almanya gibi ülkelerde aşırı akımlara destek artırmış; Nazi Partisi bu ortamda iktidara gelmiştir.'),
  ('Hitler\'in 1933\'te Almanya\'da hangi görevle iktidara geldiği aşağıdakilerden hangisidir?', 'Şansölye olarak atanmasıyla', ['Darbe ile cumhurbaşkanı olmasıyla', 'Kral tarafından imparator ilan edilmesiyle', 'Halk oylamasıyla başbakan seçilmesiyle'], 'Hitler, Ocak 1933\'te Cumhurbaşkanı Hindenburg tarafından şansölye olarak atanmış; Hindenburg\'un 1934\'te ölmesiyle "Führer" olarak tüm yetkileri toplamıştır.'),
  ('İtalya\'nın 1935-1936\'da işgal ettiği Afrika ülkesi hangisidir?', 'Habeşistan', ['Libya', 'Cezayir', 'Mısır'], 'İtalya\'nın Habeşistan\'ı (Etiyopya) işgali, Milletler Cemiyeti\'nin saldırganlığı önlemedeki etkisizliğini açıkça ortaya koymuştur. Libya ise 1911-1912\'de İtalya\'nın eline geçmişti.'),
  ('1936-1939 İspanya İç Savaşı\'nın II. Dünya Savaşı\'nın provası olarak nitelendirilmesinin nedeni nedir?', 'Almanya ve İtalya\'nın yeni silahlarını burada denemesi', ['Savaşın İspanya\'nın sömürgelerinde geçmesi', 'ABD ile Japonya\'nın İspanya\'da çatışması', 'Savaşın sonunda Milletler Cemiyeti\'nin kurulmasına yol açması'], 'Almanya ve İtalya Franco\'yu, Sovyetler Cumhuriyetçileri desteklemiş; Almanların Guernica bombardımanı gibi olaylar sonraki savaşın taktiklerini önceden göstermiştir.'),
  ('1938 Münih Konferansı\'nda İngiltere ve Fransa\'nın Almanya\'ya karşı izlediği politika hangisidir?', 'Yatıştırma politikası', ['Çevreleme politikası', 'Yumuşama politikası', 'Caydırıcılık politikası'], 'Münih\'te İngiltere ve Fransa savaştan kaçınmak için Çekoslovakya\'nın Südet bölgesinin Almanya\'ya verilmesini kabul etmiş; bu politika "appeasement" (yatıştırma) olarak bilinir.'),
  ('BM Güvenlik Konseyi\'nde daimi üyelere tanınan veto hakkının örgütün işleyişine en önemli etkisi nedir?', 'Büyük devletlerin çıkarlarına aykırı kararların alınamaması', ['Genel Kurul\'un tümüyle işlevsiz hâle gelmesi ve toplanamaması', 'Küçük devletlerin konseye üye olamaması', 'Örgütün bütçesinin daimi üyelerce karşılanması'], 'Tek bir daimi üyenin vetosu kararı engellediğinden, özellikle Soğuk Savaş döneminde Güvenlik Konseyi pek çok bunalımda karar alamamıştır.'),
  ('ABD\'nin Soğuk Savaş boyunca komünizmin yayılmasını durdurmak için izlediği genel strateji hangi adla bilinir?', 'Çevreleme (containment)', ['Yatıştırma (appeasement)', 'Yalnızcılık (isolationism)', 'Yumuşama (détente)'], 'George Kennan\'ın fikirlerine dayanan çevreleme politikası, Sovyet etkisinin sınırlandırılmasını amaçlamış; Truman Doktrini ve NATO bu stratejinin ürünleridir.'),
  ('1948-1949 Berlin Ablukası\'nda Batılı devletler Batı Berlin\'in ihtiyaçlarını nasıl karşılamıştır?', 'Hava köprüsüyle', ['Kara yolu konvoylarıyla', 'Deniz yoluyla Spree Nehri\'nden', 'Sovyetlerle yapılan ticaret antlaşmasıyla'], 'Sovyetlerin kara ve demir yollarını kapatması üzerine ABD ve İngiltere yaklaşık bir yıl boyunca Batı Berlin\'e uçaklarla yiyecek ve yakıt taşımıştır.'),
  ('Almanya\'nın 1949\'da iki ayrı devlete bölünmesi Soğuk Savaş açısından neyi simgeler?', 'Doğu ve Batı bloklarının Avrupa\'daki ayrışmasını', ['Almanya\'nın yeniden bir imparatorluk olarak kurulmasını', 'Sovyetler Birliği\'nin dağılmasını', 'Avrupa Birliği\'nin kurulmasını'], 'Federal Almanya Cumhuriyeti Batı\'ya, Demokratik Almanya Cumhuriyeti Doğu blokuna bağlanmış; Almanya Soğuk Savaş\'ın cephe hattı olmuştur.'),
  ('1956\'da Sovyet birliklerinin müdahalesiyle bastırılan halk ayaklanması hangi ülkede yaşanmıştır?', 'Macaristan', ['Polonya', 'Yugoslavya', 'Arnavutluk'], 'Ekim-Kasım 1956\'daki Macar Devrimi, Imre Nagy hükümetinin Varşova Paktı\'ndan çekilme kararının ardından Sovyet tanklarıyla bastırılmıştır.'),
  ('Kore Savaşı\'nda Türk Tugayı\'nın en ağır kayıplar verdiği ve kahramanlığıyla tanındığı muharebe hangisidir?', 'Kunuri Muharebesi', ['İnchon Çıkarması', 'Dien Bien Phu Muharebesi', 'Tet Saldırısı'], 'Kasım 1950\'de Kunuri\'de Türk Tugayı, Çin kuvvetlerine karşı BM birliklerinin geri çekilmesini korumuş ve büyük kayıplar vermiştir.'),
  ('Kore Savaşı 1953\'te ateşkesle sona ermiştir. Savaşın sonucunu en iyi ifade eden seçenek hangisidir?', 'Sınırın büyük ölçüde savaş öncesine yakın kalması', ['Kore\'nin tek devlet olarak birleşmesi', 'Güney Kore\'nin Çin\'e bağlanması', 'Kuzey Kore\'nin BM\'ye tam üye olarak kabul edilmesi'], 'Panmunjom ateşkesiyle cephe hattı 38. paralel civarında sabitlenmiş; iki Kore arasında bugün hâlâ resmî bir barış antlaşması yoktur.'),
  ('Küba Füze Krizi\'nin çözümünde Türkiye\'yi doğrudan ilgilendiren gelişme aşağıdakilerden hangisidir?', 'Jüpiter füzelerinin Türkiye\'den sökülmesi', ['Türkiye\'nin NATO\'dan çıkarılması', 'Boğazların Sovyet savaş gemilerine kesin olarak kapatılması', 'Türkiye\'ye yeni nükleer üsler kurulması'], 'Kriz sonunda Sovyetler Küba\'dan füzelerini çekmiş; ABD de gizli bir anlaşmayla Türkiye ve İtalya\'daki Jüpiter füzelerini sökmüştür.'),
  ('Küba Füze Krizi\'nden sonra ABD ile SSCB arasında doğrudan ve hızlı iletişimi sağlamak için kurulan sistem hangisidir?', 'Kırmızı telefon', ['Interkozmos ağı', 'NORAD radar hattı', 'Echelon uydu izleme sistemi'], 'Krizde iletişimin gecikmesi büyük tehlike yarattığından 1963\'te Washington ile Moskova arasında doğrudan iletişim hattı kurulmuştur.'),
  ('ABD\'nin Vietnam Savaşı\'na doğrudan ve büyük çapta katılmasının gerekçesi olarak gösterilen düşünce hangisidir?', 'Domino teorisi', ['Monroe Doktrini', 'Brejnev Doktrini', 'Eisenhower Doktrini'], 'Domino teorisine göre bir ülkenin komünist olması komşularının da sırayla komünizme geçmesine yol açacaktı; ABD bu nedenle Güney Vietnam\'ı desteklemiştir.'),
  ('Vietnam Savaşı\'nın ABD iç politikasına etkisi aşağıdakilerden hangisidir?', 'Geniş çaplı savaş karşıtı protestoların ortaya çıkması', ['ABD\'nin NATO\'dan çekilmesi', 'Başkanlık sisteminin kaldırılması', 'ABD\'nin Kore Yarımadası\'na yeniden asker göndermesi'], 'Ağır kayıplar ve televizyonda yayımlanan görüntüler ABD\'de büyük bir savaş karşıtı hareket doğurmuş; bu durum ABD\'nin 1973\'te çekilmesinde etkili olmuştur.'),
  ('Vietnam Savaşı hangi yıl Kuzey Vietnam kuvvetlerinin Saygon\'u almasıyla sona ermiştir?', '1975', ['1968', '1973', '1979'], 'Nisan 1975\'te Saygon\'un düşmesiyle savaş bitmiş ve Vietnam 1976\'da komünist yönetim altında birleşmiştir. ABD birlikleri ise 1973 Paris Barış Antlaşması\'yla çekilmişti.'),
  ('Cezayir\'in Fransa\'dan bağımsızlığını kazandığı yıl hangisidir?', '1962', ['1954', '1958', '1968'], '1954\'te başlayan Cezayir Bağımsızlık Savaşı, Evian Antlaşmaları\'nın ardından 1962\'de Cezayir\'in bağımsızlığıyla sonuçlanmıştır.'),
  ('1960 yılının "Afrika Yılı" olarak anılmasının nedeni nedir?', 'Çok sayıda Afrika ülkesinin aynı yıl bağımsızlığını kazanması', ['Afrika Birliği\'nin bu yıl kurulması', 'Güney Afrika\'da ırk ayrımcılığının sona ermesi', 'Mısır\'ın Süveyş Kanalı\'nı millîleştirmesi ve kapatması'], '1960\'ta Nijerya, Kongo, Senegal ve Madagaskar gibi on yedi Afrika ülkesi bağımsızlığını ilan etmiştir.'),
  ('Bağlantısızlar Hareketi\'nin kurucu liderleri arasında aşağıdakilerden hangisi yer almaz?', 'Charles de Gaulle', ['Josip Broz Tito', 'Cemal Abdünnasır', 'Jawaharlal Nehru'], 'Hareketin öncüleri Yugoslavya\'dan Tito, Mısır\'dan Nasır, Hindistan\'dan Nehru, Endonezya\'dan Sukarno ve Gana\'dan Nkrumah\'tır. De Gaulle Batı blokundaki Fransa\'nın lideridir.'),
  ('1917\'de İngiltere\'nin Filistin\'de Yahudiler için "ulusal yurt" kurulmasını desteklediğini açıkladığı belge hangisidir?', 'Balfour Deklarasyonu', ['Sykes-Picot Antlaşması', 'McMahon Yazışmaları', 'San Remo Kararları'], 'İngiliz Dışişleri Bakanı Arthur Balfour\'un 1917 tarihli mektubu Siyonist harekete destek vermiş ve İsrail\'in kuruluş sürecinde önemli bir dayanak olmuştur.'),
  ('1956 Süveyş Krizi\'nin doğrudan nedeni aşağıdakilerden hangisidir?', 'Mısır\'ın Süveyş Kanalı\'nı millîleştirmesi', ['İsrail\'in Kudüs\'ü başkent ilan etmesi ve ABD\'nin bunu tanıması', 'Suriye\'nin Mısır ile birleşmesi', 'Ürdün\'ün İngiltere\'ye savaş açması'], 'Cemal Abdünnasır\'ın Temmuz 1956\'da kanalı millîleştirmesi üzerine İngiltere, Fransa ve İsrail Mısır\'a saldırmış; ABD ve SSCB\'nin baskısıyla geri çekilmişlerdir.'),
  ('1967\'deki Altı Gün Savaşı\'nda İsrail\'in ele geçirdiği topraklar arasında aşağıdakilerden hangisi yer almaz?', 'Lübnan\'ın başkenti Beyrut', ['Golan Tepeleri', 'Sina Yarımadası', 'Batı Şeria'], 'İsrail 1967\'de Mısır\'dan Sina ve Gazze\'yi, Ürdün\'den Batı Şeria ve Doğu Kudüs\'ü, Suriye\'den Golan Tepeleri\'ni almıştır. Beyrut bu savaşta işgal edilmemiştir.'),
  ('1973 Yom Kippur (Ekim) Savaşı\'nın dünya ekonomisine etkisi aşağıdakilerden hangisidir?', 'Arap petrol ambargosuyla petrol fiyatlarının hızla yükselmesi', ['Altın fiyatlarının sert biçimde düşmesi', 'Süveyş Kanalı\'nın kalıcı olarak kapanması', 'Avrupa\'da ortak para biriminin hemen kabul edilmesi'], 'OPEC\'in Arap üyeleri İsrail\'i destekleyen ülkelere petrol ambargosu uygulamış; petrol fiyatları birkaç kat artarak 1973 Petrol Krizi yaşanmıştır.'),
  ('1979 İran İslam Devrimi ile devrilen hükümdar kimdir?', 'Muhammed Rıza Pehlevi', ['Rıza Şah Pehlevi', 'Ahmed Şah Kaçar', 'Musaddık'], 'Ayetullah Humeyni önderliğindeki devrimle Şah Muhammed Rıza Pehlevi ülkeyi terk etmiş ve İran İslam Cumhuriyeti ilan edilmiştir.'),
  ('1993\'te İsrail ile Filistin Kurtuluş Örgütü arasında karşılıklı tanımayı öngören anlaşmalar hangisidir?', 'Oslo Anlaşmaları', ['Camp David Anlaşmaları', 'Balfour Deklarasyonu', 'Madrid Bildirgesi'], 'Yitzhak Rabin ile Yaser Arafat\'ın imzaladığı Oslo Anlaşmaları, Filistin Ulusal Yönetimi\'nin kurulmasının yolunu açmıştır.'),
  ('Mao\'nun 1958\'de başlattığı ve tarım ile sanayide hızlı atılım hedefleyip büyük bir kıtlığa yol açan politika hangisidir?', 'Büyük İleri Atılım', ['Kültür Devrimi', 'Yüz Çiçek Kampanyası', 'Dört Modernleşme Programı'], 'Büyük İleri Atılım, köy komünleri ve arka bahçe fırınlarıyla hızlı sanayileşmeyi amaçlamış; ancak milyonlarca kişinin öldüğü bir kıtlığa yol açmıştır.'),
  ('1934-1935\'te Çin komünistlerinin Milliyetçilerin kuşatmasından kurtulmak için yaptığı ve binlerce kilometre süren çekilme hangisidir?', 'Uzun Yürüyüş', ['Büyük İleri Atılım', 'Kuzey Seferi', 'Yüz Gün Reformu'], 'Uzun Yürüyüş sırasında Mao Zedong Komünist Parti içinde liderliğini pekiştirmiştir.'),
  ('Avrupa bütünleşmesinin ilk somut adımı sayılan ve 1951\'de altı ülke tarafından kurulan örgüt hangisidir?', 'Avrupa Kömür ve Çelik Topluluğu', ['Avrupa Birliği', 'Avrupa Serbest Ticaret Birliği', 'Avrupa Güvenlik ve İşbirliği Teşkilatı'], 'Schuman Planı\'na dayanan Avrupa Kömür ve Çelik Topluluğu, Fransa, Batı Almanya, İtalya, Belçika, Hollanda ve Lüksemburg tarafından 1951 Paris Antlaşması\'yla kurulmuştur.'),
  ('Avrupa Kömür ve Çelik Topluluğu\'nun kurulmasında savaş sanayisinin temel kaynaklarının ortak denetime alınması hangi amaca hizmet etmiştir?', 'Fransa ile Almanya arasında yeni bir savaşı önlemek', ['Sovyetler Birliği\'ne kömür ihraç etmek', 'ABD\'nin Avrupa\'daki üslerini kapatmak', 'Sömürgelerdeki madenleri işletmek ve oradan gelir sağlamak'], 'Savaş için gerekli kömür ve çeliğin ortak bir otoriteye bağlanması, özellikle Fransa ile Almanya arasında savaşı "hem düşünülemez hem de maddeten imkânsız" kılmayı amaçlamıştır.'),
  ('1992\'de imzalanan ve Avrupa Birliği adını resmen ortaya koyan antlaşma hangisidir?', 'Maastricht', ['Roma', 'Nice', 'Amsterdam'], 'Maastricht Antlaşması Avrupa Birliği\'ni kurmuş, ortak para birimine (euro) geçişin takvimini belirlemiş ve AB vatandaşlığını getirmiştir.'),
  ('"Perestroyka" kavramı aşağıdakilerden hangisini ifade eder?', 'Ekonomik ve siyasi yeniden yapılanma', ['Basın ve ifade özgürlüğünde açıklık', 'Silahlanma yarışının hızlandırılması', 'Tarımın yeniden kolektifleştirilmesi ve köylülerin çiftliklere bağlanması'], 'Perestroyka yeniden yapılanma, glasnost ise açıklık anlamına gelir. Seçeneklerden ilki glasnostu tanımlar.'),
  ('Polonya\'da komünist yönetime karşı Lech Walesa önderliğinde kurulan bağımsız sendika hangisidir?', 'Dayanışma', ['Şart 77', 'Kadife Hareketi', 'Halk Cephesi'], '1980\'de Gdańsk tersanelerinde kurulan Dayanışma sendikası, Doğu Avrupa\'da komünizmin çöküşünü hızlandıran en önemli hareketlerden biri olmuştur. Şart 77 ise Çekoslovak bir insan hakları girişimidir.'),
  ('Sovyetler Birliği\'nin dağılmasıyla bağımsızlığını kazanan Türk cumhuriyetleri arasında aşağıdakilerden hangisi yer almaz?', 'Tataristan', ['Kazakistan', 'Türkmenistan', 'Kırgızistan'], '1991\'de Azerbaycan, Kazakistan, Kırgızistan, Özbekistan ve Türkmenistan bağımsız olmuştur. Tataristan ise Rusya Federasyonu\'na bağlı bir cumhuriyet olarak kalmıştır.'),
  ('Soğuk Savaş\'ın sona ermesinin ardından dünya siyasetinde ortaya çıkan durum en iyi hangi ifadeyle tanımlanır?', 'İki kutuplu düzenin yerini ABD\'nin öne çıktığı yeni bir dengeye bırakması', ['Sömürgeciliğin yeniden canlanması', 'Birleşmiş Milletler\'in dağılması', 'Varşova Paktı\'nın NATO ile birleşmesi'], 'SSCB\'nin dağılmasıyla iki kutuplu sistem çökmüş, ABD tek süper güç olarak öne çıkmış ve "yeni dünya düzeni" tartışmaları başlamıştır.'),
  ('1975\'te ABD ve SSCB uzay araçlarının uzayda kenetlenmesi hangi dönemin simgesi olarak görülür?', 'Yumuşama döneminin', ['Küba Füze Krizi\'nin', 'Kore Savaşı\'nın', 'Berlin Ablukası\'nın ve Truman Doktrini\'nin'], 'Apollo-Soyuz Test Projesi, iki süper gücün détente döneminde iş birliği yapabildiğini gösteren sembolik bir olaydır.'),
  ('Uzay yarışının Soğuk Savaş içindeki önemi aşağıdakilerden hangisiyle en iyi açıklanır?', 'Teknolojik üstünlüğün ideolojik bir prestij aracı olarak kullanılması', ['İki ülkenin uzay programlarını tümüyle birleştirmesi', 'Askerî teknolojinin uzaydan tamamen yasaklanması', 'Uzayın tek bir devlete ait ilan edilmesi'], 'Her iki süper güç de uzaydaki başarılarını kendi sisteminin üstünlüğünün kanıtı olarak sunmuş; roket teknolojisi aynı zamanda kıtalararası füze kapasitesini de göstermiştir.'),
  ('1969\'da ABD\'de askerî amaçlarla geliştirilen ve günümüz internetinin öncüsü sayılan bilgisayar ağı hangisidir?', 'ARPANET', ['ETHERNET', 'USENET', 'BITNET'], 'ABD Savunma Bakanlığı\'na bağlı ARPA\'nın kurduğu ARPANET, 1969\'da ilk bağlantıları gerçekleştirmiş ve internetin temelini oluşturmuştur.'),
  ('Batı Anadolu\'da Yunan işgaline karşı direnişi örgütlemek amacıyla 1919-1920 yıllarında toplanan bölgesel kongreler arasında aşağıdakilerden hangisi yer alır?', 'Alaşehir Kongresi', ['Pozantı Kongresi', 'Erzurum Kongresi', 'Sivas Kongresi ve Amasya Görüşmeleri'], 'Balıkesir, Alaşehir ve Nazilli kongreleri Batı Anadolu\'da Yunan işgaline karşı Kuvâ-yı Milliye\'yi örgütlemek için toplanmıştır. Pozantı Kongresi Güney\'de Fransız işgaline karşı yapılmıştır.'),
  ('Heyet-i Temsiliye başkanı olarak Mustafa Kemal hangi tarihte Ankara\'ya gelmiştir?', '27 Aralık 1919', ['23 Nisan 1920', '19 Mayıs 1919', '13 Ekim 1923'], 'Mustafa Kemal ve Heyet-i Temsiliye 27 Aralık 1919\'da Ankara\'ya gelmiş; bu tarih Ankara\'nın Millî Mücadele\'nin merkezi oluşunun başlangıcıdır.'),
  ('TBMM\'ye karşı İstanbul hükümetinin Kuvâ-yı Milliye ile savaşmak için kurduğu ve halk arasında "Hilafet Ordusu" olarak bilinen birlik hangisidir?', 'Kuvâ-yı İnzibatiye', ['Kuvâ-yı Seyyare', 'Kuvâ-yı Milliye', 'Kuvâ-yı Şarkiye'], 'Kuvâ-yı İnzibatiye, Nisan 1920\'de İstanbul hükümetince kurulmuş ve Anadolu\'daki millî hareketi bastırmak için kullanılmış; ancak kısa sürede dağıtılmıştır.'),
  ('Mustafa Kemal\'in Amasya Genelgesi\'nden sonra yayımladığı ve askerî birliklerin dağıtılmamasını, silahların teslim edilmemesini isteyen genelge aşağıdakilerden hangisinin hedefini yansıtır?', 'Millî direnişin askerî gücünü korumayı', ['Ordunun tümüyle terhis edilmesini', 'İtilaf Devletleri ile iş birliği yapılmasını', 'Silahların İstanbul\'a gönderilmesini'], 'Mustafa Kemal, Mondros gereği yapılmak istenen terhis ve silah teslimini engelleyerek Millî Mücadele\'nin askerî temelini korumaya çalışmıştır.'),
  ('Erzurum Kongresi\'ne başlangıçta hangi cemiyet çağrı yapmıştır?', 'Vilayât-ı Şarkiye Müdafaa-i Hukuk Cemiyeti', ['Trakya-Paşaeli Müdafaa-i Hukuk Cemiyeti', 'Kilikyalılar Cemiyeti', 'İzmir Müdafaa-i Hukuk Cemiyeti'], 'Erzurum Kongresi, Doğu illerini Ermeni iddialarına karşı korumak amacıyla Vilayât-ı Şarkiye Müdafaa-i Hukuk Cemiyeti\'nin girişimiyle toplanmıştır.'),
  ('II. İnönü Muharebesi\'nin ardından İtalyanların Anadolu\'dan çekilmeye başlaması Millî Mücadele açısından ne anlama gelir?', 'İtilaf cephesinde ilk çözülmenin yaşanması', ['İtalya\'nın TBMM\'ye savaş ilan etmesi', 'Yunanistan\'ın İtalya ile birleşmesi', 'Sevr\'in tümüyle uygulanmaya başlaması'], 'İtalya, İzmir\'in Yunanistan\'a verilmesinden memnun değildi; Türk zaferleri karşısında Anadolu\'dan çekilmeye başlaması İtilaf birliğinin bozulduğunu göstermiştir.'),
  ('Lozan Konferansı\'nda İngiltere\'yi temsil eden ve Türk heyetiyle sert tartışmalar yaşayan dışişleri bakanı kimdir?', 'Lord Curzon', ['Lloyd George', 'Winston Churchill', 'Neville Chamberlain'], 'Lozan\'ın ilk döneminde İngiliz heyetinin başında Lord Curzon bulunmuş; İsmet Paşa ile özellikle Musul ve kapitülasyonlar konusunda sert tartışmalar yaşanmıştır.'),
  ('İstanbul 6 Ekim 1923\'te Türk ordusu tarafından teslim alınmıştır. Bu gelişme hangi antlaşmanın sonucudur?', 'Lozan Antlaşması', ['Mudanya Ateşkesi', 'Mondros Ateşkesi', 'Montrö Sözleşmesi'], 'Lozan\'ın imzalanmasının ardından İtilaf kuvvetleri İstanbul\'u boşaltmış ve 6 Ekim 1923\'te Türk birlikleri şehre girmiştir.'),
  ('Saltanatın kaldırılmasıyla birlikte Osmanlı Devleti\'nin hukuken sona ermesi neyi ifade eder?', 'TBMM\'nin tek meşru yönetim olarak kalmasını', ['Halifeliğin de aynı anda sona ermesini', 'Cumhuriyetin ilan edilmiş olmasını', 'Lozan\'ın imzalanmasını'], '1 Kasım 1922 kararıyla İstanbul hükümetinin varlığı sona ermiş, yönetimdeki ikilik kalkmış ve TBMM tek meşru güç hâline gelmiştir.'),
  ('1924\'te Atatürk\'ün desteğiyle kurulan ve Cumhuriyet\'in ilk ulusal bankası olan kuruluş hangisidir?', 'Türkiye İş Bankası', ['Türkiye Cumhuriyet Merkez Bankası', 'Sümerbank', 'Ziraat Bankası ve Emniyet Sandığı'], 'Türkiye İş Bankası 26 Ağustos 1924\'te Celal Bayar\'ın genel müdürlüğünde kurulmuş; özel sermayeyi desteklemeyi amaçlamıştır. Ziraat Bankası Osmanlı döneminde kurulmuştur.'),
  ('1926\'da Uşak ve Alpullu\'da kurulan fabrikalar hangi sanayi koluna aittir?', 'Şeker sanayisine', ['Demir-çelik sanayisine', 'Dokuma ve iplik sanayisine', 'Kâğıt ve selüloz sanayisine'], 'Uşak ve Alpullu şeker fabrikaları Cumhuriyet\'in ilk şeker fabrikalarıdır; bu sayede şeker ithalatına bağımlılığın azaltılması amaçlanmıştır.'),
  ('Cumhuriyet döneminde yabancı şirketlere ait demiryollarının satın alınarak devletleştirilmesi hangi amaca yöneliktir?', 'Ulaşımda ekonomik bağımsızlığı sağlamak', ['Demiryolu yapımını tümüyle durdurmak', 'Ulaşımı yalnız deniz yoluna kaydırmak', 'Yabancı sermayeyi teşvik etmek ve vergi muafiyeti tanımak'], 'Osmanlı döneminde yabancılara verilen demiryolu imtiyazları ekonomik bağımlılık yaratıyordu; devletleştirme ve yeni hatların yapımı millî ekonomiyi güçlendirmiştir.'),
  ('Cumhuriyet\'in ilk genel nüfus sayımı hangi yıl yapılmıştır?', '1927', ['1923', '1935', '1924'], 'Türkiye\'de ilk genel nüfus sayımı 28 Ekim 1927\'de yapılmış ve nüfus yaklaşık 13,6 milyon olarak belirlenmiştir.'),
  ('Atatürk\'ün isteğiyle 1935\'te Ankara\'da açılan ve Türk tarihi ile dilinin bilimsel olarak araştırılmasını amaçlayan fakülte hangisidir?', 'Dil ve Tarih-Coğrafya Fakültesi', ['Edebiyat Fakültesi ve Darülfünun', 'Siyasal Bilgiler Fakültesi', 'İlahiyat Fakültesi'], 'Dil ve Tarih-Coğrafya Fakültesi, Türk Tarih Kurumu ve Türk Dil Kurumu\'nun çalışmalarını akademik düzeyde sürdürmek için kurulmuştur.'),
  ('1934\'te kabul edilen bir kanunla din adamlarının dinî kıyafetlerini yalnız ibadet yerlerinde ve dinî törenlerde giyebilmesi öngörülmüştür. Bu düzenleme aşağıdakilerden hangisiyle doğrudan ilgilidir?', 'Laiklik ilkesi', ['Devletçilik ilkesi', 'Milliyetçilik ve millî ekonomi anlayışı', 'Cumhuriyetçilik ilkesi'], 'Bazı Kisvelerin Giyilemeyeceğine Dair Kanun, din adamlarının kıyafetini dinî alanla sınırlandırarak din ile kamusal hayatın ayrılmasını amaçlamıştır.'),
  ('Türkiye\'nin 1941\'de Almanya ile imzaladığı Saldırmazlık Paktı\'nın Türk dış politikasındaki anlamı nedir?', 'Savaş dışı kalma çabasının bir parçası olması', ['Türkiye\'nin Mihver safında savaşa girmesi', 'İngiltere ile ilişkilerin tümüyle kesilmesi', 'Türkiye\'nin Balkan topraklarını Almanya\'ya bırakması'], 'Almanya Balkanlara ulaştığında imzalanan bu pakt, Türkiye\'nin her iki tarafla da dengeli ilişki kurarak savaşa girmeme politikasının ürünüdür.'),
  ('1945\'te Meclis\'te Celal Bayar, Adnan Menderes, Refik Koraltan ve Fuat Köprülü\'nün verdiği ve çok partili hayatın başlangıcı sayılan önerge hangi adla bilinir?', 'Dörtlü Takrir', ['Misak-ı İktisadi', 'Kara Kitap', 'Millî Korunma Önergesi ve Kanunu'], 'Dörtlü Takrir, Çiftçiyi Topraklandırma Kanunu tartışmaları sırasında verilmiş; demokratikleşme ve anayasanın tam uygulanmasını istemiştir. Önerge reddedilmiş ve DP kurulmuştur.'),
  ('1945\'te çıkarılan ve Demokrat Parti\'nin kurulmasına giden tartışmaları başlatan kanun hangisidir?', 'Çiftçiyi Topraklandırma Kanunu', ['Varlık Vergisi Kanunu', 'Takrir-i Sükûn Kanunu', 'Toprak Mahsulleri Vergisi'], 'Topraksız köylüye toprak dağıtmayı öngören bu kanun büyük toprak sahiplerinin tepkisini çekmiş; Adnan Menderes gibi milletvekilleri kanuna karşı çıkmıştır.'),
  ('1961 Anayasası\'nın ilk kez halkoylamasına sunulan anayasa olmasının önemi nedir?', 'Anayasanın meşruiyetini doğrudan halk onayına dayandırması', ['Anayasanın meclis tarafından hiç görüşülmemesi', 'Seçme hakkının kaldırılması', 'Cumhurbaşkanının halk tarafından seçilmesi ve yetkilerinin artırılması'], '1961 Anayasası 9 Temmuz 1961\'de halkoyuna sunularak kabul edilmiştir; daha önceki anayasalar yalnızca meclislerce kabul edilmişti.'),
  ('Kıbrıs\'ın Yunanistan\'a bağlanmasını amaçlayan Rum düşüncesinin adı nedir?', 'Enosis', ['Taksim', 'Megali İdea ve Pontus', 'Filiki Eterya'], 'Enosis, Kıbrıs\'ın Yunanistan\'a ilhakını öngören Rum milliyetçi hedefidir; Türk tarafının adanın bölünmesi önerisi ise "taksim" olarak anılmıştır.'),
  ('Almanya\'nın I. Dünya Savaşı başında Fransa\'yı Belçika üzerinden hızla yenip ardından Rusya\'ya yönelmeyi öngören planı hangisidir?', 'Schlieffen Planı', ['Marshall Planı', 'Dawes Planı', 'Morgenthau Planı'], 'Schlieffen Planı iki cepheli savaştan kaçınmayı amaçlıyordu; ancak Marne Muharebesi\'nde durdurulunca Batı Cephesi siper savaşına dönüşmüştür. Dawes Planı ise 1924\'te tazminatların düzenlenmesidir.'),
  ('I. Dünya Savaşı\'nda tank, zehirli gaz ve uçak gibi yeni silahların kullanılması savaşın hangi özelliğini öne çıkarmıştır?', 'Sanayi ve teknolojinin savaşın sonucunu belirlemesini', ['Savaşın yalnız süvari birlikleriyle yapılmasını', 'Sivillerin savaştan hiç etkilenmemesini', 'Cephelerin çok kısa sürede kapanmasını ve barışın hızla gelmesini'], 'I. Dünya Savaşı, ülkelerin bütün sanayi gücünü seferber ettiği ilk topyekûn savaşlardandır; yeni silahlar kayıpların görülmemiş boyutlara ulaşmasına yol açmıştır.'),
  ('I. Dünya Savaşı\'nı sona erdiren Paris Barış Konferansı\'nda kararları belirleyen "Dörtler" arasında aşağıdakilerden hangisi yer almaz?', 'Lenin', ['Woodrow Wilson', 'Georges Clemenceau', 'David Lloyd George'], 'Konferansın belirleyici isimleri ABD\'den Wilson, Fransa\'dan Clemenceau, İngiltere\'den Lloyd George ve İtalya\'dan Orlando\'dur. Sovyet Rusya konferansa çağrılmamıştır.'),
  ('Versay Antlaşması ile Almanya\'dan alınarak Fransa\'ya bırakılan bölge hangisidir?', 'Alsas-Loren', ['Südet bölgesi', 'Ruhr Havzası\'nın tamamı', 'Danzig Koridoru'], '1871\'de Almanya\'ya geçen Alsas-Loren, Versay ile Fransa\'ya geri verilmiştir. Ruhr ise 1923\'te Fransa ve Belçika tarafından geçici olarak işgal edilmiştir.'),
  ('1917 Şubat Devrimi\'nin sonucu aşağıdakilerden hangisidir?', 'Çarlığın yıkılıp geçici hükümetin kurulması', ['Bolşeviklerin iktidarı ele geçirmesi', 'Sovyetler Birliği\'nin resmen kurulması', 'Rusya\'nın savaştan hemen çekilmesi ve barış imzalaması'], 'Şubat Devrimi ile II. Nikola tahttan çekilmiş ve geçici hükümet kurulmuştur. Bolşevikler ise Ekim Devrimi\'yle iktidara gelmiştir.'),
  ('Rus Devrimi\'nin ardından 1918-1921 arasında Bolşevikler ile karşıtları arasında yaşanan iç savaşta tarafların genel adları nedir?', 'Kızıllar ve Beyazlar', ['Yeşiller ve Siyahlar', 'Mavi Gömlekliler ve Kara Gömlekliler', 'Menşevikler ve Narodnikler'], 'Kızıl Ordu Bolşevikleri, Beyaz Ordu ise çarlık yanlıları ve diğer karşıtları temsil ediyordu; iç savaşı Bolşevikler kazanmıştır.'),
  ('Stalin\'in 1930\'larda Sovyet Komünist Partisi\'ndeki rakiplerini ve muhalifleri tasfiye ettiği dönem hangi adla anılır?', 'Büyük Temizlik', ['Kültür Devrimi', 'Yeni Ekonomik Politika', 'Destalinizasyon ve Yumuşama'], '1936-1938\'deki Büyük Temizlik\'te göstermelik yargılamalar yapılmış, yüz binlerce kişi idam edilmiş ya da Gulag kamplarına gönderilmiştir.'),
  ('1923\'te Almanya\'da yaşanan ve paranın neredeyse değersiz hâle geldiği ekonomik olay aşağıdakilerden hangisidir?', 'Hiperenflasyon', ['Deflasyon', 'Büyük Buhran', 'Petrol Krizi ve stagflasyon'], 'Savaş tazminatları ve Ruhr\'un işgali nedeniyle Alman markı 1923\'te çökmüş; fiyatlar saatler içinde değişecek kadar artmıştır.'),
  ('Japonya\'nın 1931\'de işgal ederek kukla bir devlet kurduğu Çin bölgesi hangisidir?', 'Mançurya', ['Kore', 'Tayvan', 'Tibet'], 'Japonya 1931\'de Mançurya\'yı işgal edip Mançukuo adlı kukla devleti kurmuş; Milletler Cemiyeti\'nin kınaması üzerine örgütten çekilmiştir.'),
  ('Milletler Cemiyeti\'nin 1930\'larda saldırgan devletleri durduramamasının temel nedeni aşağıdakilerden hangisidir?', 'Kararlarını uygulatacak askerî gücünün bulunmaması', ['Bütün büyük devletlerin örgüte üye olması', 'Örgütün yalnız Asya ülkelerinden oluşması', 'Örgütün merkezinin ABD\'de bulunması ve uzaklığı'], 'Milletler Cemiyeti\'nin ortak bir ordusu yoktu; ABD üye değildi, Japonya, Almanya ve İtalya ise örgütten ayrılmıştı. Bu nedenle yaptırımlar etkisiz kalmıştır.'),
  ('Almanya\'nın 1936\'da Versay Antlaşması\'nı çiğneyerek askerî birlik soktuğu bölge hangisidir?', 'Ren bölgesi', ['Alsas-Loren', 'Polonya Koridoru', 'Bohemya'], 'Versay\'a göre silahsızlandırılmış olan Ren bölgesine Mart 1936\'da Alman birlikleri girmiş; İngiltere ve Fransa buna karşılık vermemiştir.'),
  ('II. Dünya Savaşı\'nda 1940 yazında Alman hava kuvvetleri ile İngiliz hava kuvvetleri arasında yapılan mücadele hangi adla anılır?', 'Britanya Savaşı', ['Atlantik Savaşı', 'Midway Savaşı', 'Kursk Muharebesi ve tank savaşları'], 'Britanya Savaşı\'nda Luftwaffe İngiltere\'yi teslim almaya çalışmış; RAF\'ın direnişi Almanya\'nın İngiltere\'yi işgal planını ertelemesine yol açmıştır.'),
  ('Kuzey Afrika\'da 1942\'de İngilizlerin Rommel komutasındaki Alman-İtalyan kuvvetlerini durdurduğu muharebe hangisidir?', 'El Alamein', ['Tobruk Kuşatması\'nın sonu ve Bingazi', 'Kasserine', 'Dunkirk'], 'Montgomery komutasındaki İngiliz kuvvetleri Ekim-Kasım 1942\'de El Alamein\'de zafer kazanmış; Mihver kuvvetleri Kuzey Afrika\'da geri çekilmeye başlamıştır.'),
  ('1941\'de Roosevelt ile Churchill\'in savaş sonrası dünyaya ilişkin ilkeleri açıkladığı ve BM\'nin temellerinden sayılan belge hangisidir?', 'Atlantik Bildirisi', ['Truman Doktrini', 'Versay Antlaşması', 'Locarno Antlaşması'], 'Ağustos 1941\'de bir savaş gemisinde açıklanan Atlantik Bildirisi, toprak genişlemesinin reddi ve halkların kendi yönetimlerini seçme hakkı gibi ilkeleri içerir.'),
  ('II. Dünya Savaşı sonrasında yenilen Almanya\'nın yönetimiyle ilgili hangi karar Potsdam Konferansı\'nda kesinleşmiştir?', 'Dört işgal bölgesine ayrılarak yönetilmesi', ['Hemen birleşik ve bağımsız bir devlet olması', 'Tamamen Sovyetler Birliği\'ne bağlanması', 'Fransa\'ya ilhak edilmesi ve Ren\'in sınır olması'], 'Temmuz-Ağustos 1945 Potsdam Konferansı\'nda Almanya\'nın ABD, İngiltere, Fransa ve SSCB arasında dört işgal bölgesine ayrılması ve Nazizmden arındırılması kararlaştırılmıştır.'),
  ('Sovyetler Birliği\'nin Marshall Planı\'na karşılık 1949\'da Doğu bloku ülkeleriyle kurduğu ekonomik örgüt hangisidir?', 'COMECON', ['Kominform', 'Varşova Paktı', 'OPEC'], 'Karşılıklı Ekonomik Yardım Konseyi (COMECON), Doğu bloku ekonomilerini Sovyetler Birliği çevresinde bütünleştirmek amacıyla kurulmuştur.'),
  ('Soğuk Savaş döneminde ABD\'de komünist olduğundan şüphelenilen kişilere yönelik soruşturmalar ve baskılar hangi senatörün adıyla anılır?', 'McCarthycilik', ['Wilsonculuk', 'Monroeculuk', 'Keynesçilik'], '1950\'lerin başında Senatör Joseph McCarthy\'nin öncülüğündeki "kızıl korku" kampanyasında pek çok kişi kanıtsız suçlamalarla kara listelere alınmıştır.'),
  ('Türkiye\'nin ilk kadın başbakanı kimdir ve hangi yıl bu göreve gelmiştir?', 'Tansu Çiller, 1993', ['Türkan Akyol, 1971', 'Meral Akşener, 1996', 'Tansu Çiller, 1987'], 'Doğru Yol Partisi genel başkanı Tansu Çiller, Haziran 1993\'te başbakan olarak Türkiye\'nin ilk kadın başbakanı olmuştur. Türkan Akyol ise 1971\'de ilk kadın bakan olmuştur.'),
  ('Türkiye ile Avrupa Birliği arasındaki Gümrük Birliği hangi yıl yürürlüğe girmiştir?', '1996', ['1987', '1963', '2005'], 'Gümrük Birliği 1 Ocak 1996\'da yürürlüğe girmiştir. 1963 Ankara Antlaşması, 1987 tam üyelik başvurusu, 2005 ise katılım müzakerelerinin başladığı yıldır.'),
  ('1992\'de Türkiye\'nin öncülüğünde İstanbul\'da kurulan ve Karadeniz\'e kıyısı olan ve bölgedeki ülkeleri bir araya getiren ekonomik örgüt hangisidir?', 'Karadeniz Ekonomik İşbirliği Örgütü', ['Ekonomik İşbirliği Teşkilatı', 'Bağımsız Devletler Topluluğu', 'Avrupa Serbest Ticaret Birliği'], 'Karadeniz Ekonomik İşbirliği, 25 Haziran 1992\'de İstanbul\'da imzalanan bildiriyle kurulmuştur. Ekonomik İşbirliği Teşkilatı ise Türkiye, İran ve Pakistan\'ın kurduğu örgüttür.'),
  ('Bir köyde yaşayan Ayşe Hanım 1930\'larda okuma yazma öğrenmiş, belediye ve milletvekili seçimlerinde oy kullanmış ve resmî nikâhla evlenmiştir. Bu yaşam öyküsü hangi alandaki inkılapların toplumsal etkisini birlikte gösterir?', 'Eğitim, siyasi haklar ve hukuk alanlarının', ['Yalnızca ekonomi ve sanayi alanlarının', 'Dış politika ve askerî düzenlemelerin', 'Ölçü, tartı ve takvim düzenlemelerinin'], 'Okuma yazma Harf İnkılabı ve Millet Mektepleri\'ni, oy kullanma 1930-1934 düzenlemelerini, resmî nikâh ise Medeni Kanun\'u yansıtır.'),
  ('Aşağıdaki gelişmelerden hangisi Atatürk\'ün halkçılık ilkesinin doğrudan bir uygulamasıdır?', 'Aşar vergisinin kaldırılması', ['Montrö Sözleşmesi\'nin imzalanması', 'Harf İnkılabı\'nın yapılması ve yeni alfabe', 'Halifeliğin kaldırılması'], 'Köylünün ağır vergi yükünü kaldıran aşarın kaldırılması, toplumun geniş kesimlerinin yararını gözeten halkçılık anlayışının ürünüdür.'),
  ('Atatürk\'ün "Türkiye Cumhuriyeti\'ni kuran Türkiye halkına Türk milleti denir" sözü milliyetçilik anlayışının hangi özelliğini öne çıkarır?', 'Vatandaşlık bağına dayanan birleştirici bir anlayışı', ['Irk temeline dayanan dışlayıcı bir anlayışı', 'Ümmet esasına dayanan dinî bir anlayışı', 'Yalnız tek bir bölgeyi kapsayan dar bir anlayışı'], 'Bu tanım, milleti ortak vatandaşlık ve kültür bağıyla tanımlar; ırk ya da din esasına dayanmayan birleştirici bir milliyetçiliği yansıtır.'),
  ('Aşağıdakilerden hangisi devletçilik ilkesinin uygulamalarından biri değildir?', 'Medeni Kanun\'un kabul edilmesi', ['Sümerbank\'ın kurulması', 'Birinci Beş Yıllık Sanayi Planı\'nın uygulanması', 'Demiryollarının devletleştirilmesi'], 'Medeni Kanun hukuk ve laiklik alanında bir inkılaptır; diğerleri devletin ekonomiye doğrudan katıldığı devletçilik uygulamalarıdır.'),
  ('Cumhuriyetçilik ilkesiyle en doğrudan ilişkili gelişme aşağıdakilerden hangisidir?', '1946\'da çok partili hayata geçilmesi', ['Kabotaj Kanunu\'nun çıkarılması', 'Şapka Kanunu\'nun kabulü ve kılık kıyafet düzenlemeleri', 'Ölçüler Kanunu\'nun kabulü'], 'Cumhuriyetçilik millî egemenliği ve halkın yönetime katılımını esas alır; çok partili hayat bu katılımın genişlemesini sağlamıştır.'),
  ('Atatürk\'ün manevi kızlarından biri olan, tarihçi ve Türk Tarih Kurumu\'nun kuruluşunda görev alan kişi kimdir?', 'Afet İnan', ['Sabiha Gökçen', 'Ülkü Adatepe', 'Zehra Aylin'], 'Afet İnan, Türk Tarih Kurumu çalışmalarında yer almış ve Atatürk\'ün isteğiyle hazırlanan Medeni Bilgiler kitabının yazımına katkıda bulunmuştur.'),
  ('Atatürk\'ün vatandaşlık bilgilerini anlatmak amacıyla dikte ettirdiği ve Afet İnan tarafından yayımlanan eser hangisidir?', 'Medeni Bilgiler', ['Nutuk', 'Geometri', 'Zabit ve Kumandan ile Hasbıhal'], 'Medeni Bilgiler, 1930\'da Atatürk\'ün el yazmalarına dayanılarak hazırlanmış; millet, devlet, egemenlik ve vatandaşlık gibi kavramları açıklamıştır.'),
  ('Atatürk\'ün 1919-1927 arasını anlattığı Nutuk\'u okumasının temel amacı aşağıdakilerden hangisidir?', 'Millî Mücadele ve Cumhuriyet\'in kuruluşunu belgelere dayanarak açıklamak', ['Osmanlı padişahlarının hayatlarını anlatmak', 'Dünya savaşının askerî tarihini yazmak', 'Yeni bir anayasa önerisi sunmak ve tartıştırmak'], 'Nutuk, kendisine yöneltilen eleştirilere de cevap vererek Millî Mücadele ve Cumhuriyet\'in kuruluşunu belgelerle gelecek kuşaklara aktarmayı amaçlamıştır.'),
  ('Atatürk\'ün Kurtuluş Savaşı sırasında yaptığı "Ordular, ilk hedefiniz Akdeniz\'dir" ile "Hatt-ı müdafaa yoktur, sath-ı müdafaa vardır" sözleri kronolojik olarak nasıl sıralanır?', 'Önce sath-ı müdafaa, sonra Akdeniz emri', ['Önce Akdeniz emri, sonra sath-ı müdafaa', 'İkisi de aynı gün söylenmiştir', 'İkisi de Çanakkale Savaşı\'nda söylenmiştir'], 'Sath-ı müdafaa sözü 1921 Sakarya Muharebesi\'nde, Akdeniz emri ise 1 Eylül 1922\'de Büyük Taarruz\'dan sonra verilmiştir.'),
  ('Atatürk\'ün eşi Latife Hanım ile hangi şehirde evlendiği bilinmektedir?', 'İzmir', ['Ankara', 'İstanbul', 'Selanik'], 'Atatürk, Latife Uşşakizade ile 29 Ocak 1923\'te İzmir\'de evlenmiştir; nikâhta kadının da hazır bulunması o dönem için yenilikçi sayılmıştır.'),
  ('1960\'ta Irak, İran, Kuveyt, Suudi Arabistan ve Venezuela tarafından Bağdat\'ta kurulan örgüt hangisidir?', 'OPEC', ['OECD', 'Arap Birliği', 'İslam İşbirliği Teşkilatı'], 'Petrol İhraç Eden Ülkeler Örgütü (OPEC), petrol fiyatları ve üretimi üzerinde üretici ülkelerin söz sahibi olması için kurulmuştur.'),
  ('1948 Arap-İsrail Savaşı\'nın ardından yaşanan ve yüz binlerce Filistinlinin yurdunu terk etmesine yol açan olay Filistinlilerce hangi adla anılır?', 'Nakba', ['İntifada', 'Hicret', 'Kristal Gece'], 'Arapça "felaket" anlamına gelen Nakba, 1948\'deki Filistinli göçünü ifade eder. İntifada ise 1987 ve 2000\'de başlayan Filistin halk ayaklanmalarının adıdır.'),
  ('Japonya\'nın II. Dünya Savaşı\'ndan sonra kısa sürede ekonomik bir güce dönüşmesi hangi adla anılır?', 'Japon mucizesi', ['Meiji Restorasyonu', 'Tanzimat dönemi', 'Büyük İleri Atılım ve kolektif tarım'], 'Savaş sonrası ABD işgali altında yapılan reformlar, eğitimli iş gücü ve ihracata dayalı sanayi Japonya\'yı 1960\'larda dünyanın önde gelen ekonomilerinden biri yapmıştır. Meiji Restorasyonu 19. yüzyıldadır.'),
  ('Latin Amerika\'da 1973\'te Şili\'de seçilmiş Devlet Başkanı Salvador Allende\'yi deviren darbenin lideri kimdir?', 'Augusto Pinochet', ['Fidel Castro', 'Juan Perón', 'Che Guevara ve Bolivya gerillaları'], '11 Eylül 1973\'te General Pinochet önderliğindeki darbeyle Allende hükümeti devrilmiş ve Şili\'de uzun süren askerî bir rejim kurulmuştur.'),
  ('Sovyetler Birliği\'nin dağılmasının ardından eski Sovyet cumhuriyetlerinin çoğunun 1991\'de kurduğu gevşek birlik hangisidir?', 'Bağımsız Devletler Topluluğu', ['Avrasya Ekonomik Birliği', 'Şanghay İşbirliği Örgütü', 'Varşova Paktı ve COMECON'], 'Aralık 1991\'de Minsk ve Alma-Ata\'da kurulan Bağımsız Devletler Topluluğu, Sovyetler Birliği\'nin yerini alan bir iş birliği çerçevesidir.'),
  ('Doğu Avrupa\'da 1989\'da komünist rejimin şiddetli bir ayaklanmayla devrildiği ve liderinin idam edildiği ülke hangisidir?', 'Romanya', ['Macaristan', 'Bulgaristan', 'Polonya'], 'Aralık 1989\'da Romanya\'da halk ayaklanmasıyla Nicolae Çavuşesku devrilmiş ve eşiyle birlikte idam edilmiştir; diğer ülkelerde geçiş büyük ölçüde barışçı olmuştur.'),
  ('Mustafa Kemal\'in II. Dönem TBMM seçimlerinin ardından, 9 Eylül 1923\'te kurduğu siyasi parti hangisidir?', 'Halk Fırkası', ['Terakkiperver Cumhuriyet Fırkası', 'Serbest Cumhuriyet Fırkası', 'Ahali Cumhuriyet Fırkası'], 'Mustafa Kemal 9 Eylül 1923\'te Halk Fırkası\'nı kurmuş; parti 1924\'te Cumhuriyet Halk Fırkası, 1935\'te Cumhuriyet Halk Partisi adını almıştır. Terakkiperver Cumhuriyet Fırkası 1924\'te, Serbest Cumhuriyet Fırkası ve Ahali Cumhuriyet Fırkası 1930\'da kurulmuştur.'),
  ('TBMM\'nin Millî Mücadele yıllarında Kuvâ-yı Milliye\'den düzenli orduya geçişte ilk büyük sınavı olan muharebede Türk ordusuna komuta eden kişi kimdir?', 'İsmet Bey', ['Refet Bey', 'Fahrettin Bey', 'Mustafa Kemal Paşa ve Fevzi Paşa'], 'Batı Cephesi Kuzey Kesimi Komutanı İsmet Bey, Ocak 1921\'de I. İnönü Muharebesi\'nde düzenli orduyu komuta etmiş ve İnönü soyadını bu muharebelerden almıştır.'),
  ('Kurtuluş Savaşı\'nda Yunan ordusuna karşı "Mehmetçik" ile birlikte savaşan halk kahramanları arasında yer alan Demirci Mehmet Efe hangi bölgede mücadele etmiştir?', 'Ege\'de, Aydın ve Denizli çevresinde', ['Güneydoğu\'da, Antep ve Urfa çevresinde', 'Karadeniz\'de, Samsun ve Trabzon çevresinde', 'Doğu\'da, Kars ve Erzurum çevresinde'], 'Demirci Mehmet Efe Nazilli, Aydın ve Denizli çevresinde Yunan işgaline karşı Kuvâ-yı Milliye birlikleri kurmuştur.'),
  ('Mustafa Kemal\'in Kurtuluş Savaşı\'ndan sonra 1923 başında halkla görüşmek ve İzmir İktisat Kongresi\'ni açmak için yaptığı gezi aynı zamanda hangi düşünceyi yansıtır?', 'Siyasi zaferin ekonomik zaferle tamamlanması gerektiğini', ['Askerî harekâtların yeniden başlayacağını', 'Başkentin İzmir\'e taşınacağını', 'İzmir\'in özel bir statüye kavuşacağını ve ayrılacağını'], 'Atatürk kongrenin açılışında "Siyasi ve askerî zaferler ne kadar büyük olursa olsunlar, iktisadi zaferlerle taçlandırılmazlarsa kalıcı olamaz" demiştir.'),
  ('1925\'te kabul edilen ve uluslararası saat sistemi ile miladi takvimi kabul eden düzenlemeler yürürlüğe girdiğinde Türkiye\'de hangi takvimler terk edilmiştir?', 'Hicri ve Rumi takvimler', ['Jülyen ve Gregoryen takvimler', 'Çin ve Hint takvimleri', 'Celali ve Yahudi takvimleri'], '26 Aralık 1925 kanunlarıyla 1 Ocak 1926\'dan itibaren miladi takvim ve uluslararası saat kabul edilmiş; hicri ve rumi takvim resmî kullanımdan kalkmıştır.'),
  ('1979 İran Devrimi\'nin ardından Tahran\'daki ABD Büyükelçiliği\'nde yaşanan olay hangisidir?', 'Elçilik personelinin 444 gün rehin tutulması', ['Elçiliğin bombalanması ve yıkılması', 'Elçiliğin Sovyetlere devredilmesi', 'Elçiliğin İran\'ın başkentini taşımasıyla kapanması'], 'Kasım 1979\'da devrimci öğrenciler büyükelçiliği basarak 52 Amerikalıyı rehin almış; rehineler Ocak 1981\'de serbest bırakılmıştır.'),
  ('1982\'de Arjantin ile Birleşik Krallık arasında Güney Atlantik\'teki adalar üzerinde yaşanan savaş hangisidir?', 'Falkland (Malvinas) Savaşı', ['Süveyş Savaşı', 'Körfez Savaşı', 'Grenada Harekâtı ve Panama Krizi'], 'Arjantin\'in Nisan 1982\'de Falkland Adaları\'nı işgal etmesi üzerine İngiltere adaları geri almış; savaş Haziran 1982\'de sona ermiştir.'),
  ('Kore Savaşı\'nda BM kuvvetlerinin başkomutanı olan ve Çin\'e karşı savaşı genişletmek istediği için görevden alınan Amerikan general kimdir?', 'Douglas MacArthur', ['Dwight Eisenhower', 'George Patton', 'Omar Bradley'], 'MacArthur, Inchon çıkarmasıyla başarı kazanmış; ancak Çin\'e saldırılmasını savunması üzerine Başkan Truman tarafından 1951\'de görevden alınmıştır.'),
  ('Avrupa Birliği\'nde ortak para birimi euro, nakit olarak hangi yıl tedavüle girmiştir?', '2002', ['1992', '1999', '2004'], 'Euro 1999\'da kaydi para olarak kullanılmaya başlamış, banknot ve madeni paralar ise 1 Ocak 2002\'de tedavüle girmiştir.'),
  ('Aşağıdaki savaşlardan hangisi Batı Cephesi\'nde kronolojik olarak en son yapılmıştır?', 'Başkomutan Meydan Muharebesi', ['II. İnönü Muharebesi', 'Sakarya Meydan Muharebesi', 'Kütahya-Eskişehir Muharebeleri'], 'Sıralama II. İnönü (Mart-Nisan 1921), Kütahya-Eskişehir (Temmuz 1921), Sakarya (Ağustos-Eylül 1921) ve Başkomutan Meydan Muharebesi (30 Ağustos 1922) şeklindedir.'),
  ('Aşağıdaki inkılapların hangisi Cumhuriyetin ilanından önce gerçekleştirilmiştir?', 'Saltanatın kaldırılması', ['Halifeliğin kaldırılması', 'Şapka Kanunu\'nun kabulü', 'Tevhid-i Tedrisat Kanunu\'nun kabulü'], 'Saltanat 1 Kasım 1922\'de kaldırılmıştır; Cumhuriyet 29 Ekim 1923\'te ilan edilmiş, diğer inkılaplar 1924 ve 1925\'te yapılmıştır.'),
  ('Erzurum ve Sivas kongreleri karşılaştırıldığında aşağıdakilerden hangisi yalnızca Sivas Kongresi için söylenebilir?', 'Bütün yurttan delegelerin katılması', ['Manda ve himayenin açıkça reddedilmesi', 'Temsil Heyeti\'nin seçilmesi', 'Mustafa Kemal\'in başkanlık etmesi'], 'Erzurum bölgesel, Sivas ise ulusal katılımlı bir kongredir. Manda reddi, Temsil Heyeti seçimi ve Mustafa Kemal\'in başkanlığı her iki kongrede de görülür.'),
  ('Mondros Ateşkesi ile Sevr Antlaşması karşılaştırıldığında aşağıdakilerden hangisi doğrudur?', 'Mondros askerî bir ateşkes, Sevr ise kapsamlı bir barış antlaşmasıdır', ['Mondros\'u TBMM, Sevr\'i İstanbul hükümeti imzalamıştır', 'İkisi de Osmanlı Mebusan Meclisi\'nce onaylanmış ve yürürlüğe girmiştir', 'Sevr, Mondros\'tan önce imzalanmıştır'], 'Mondros savaşı durduran ve orduyu terhis eden bir ateşkestir; Sevr ise toprak, ekonomi ve azınlıklar gibi konuları düzenleyen kapsamlı ama onaylanmamış bir barış antlaşmasıdır.'),
  ('Misak-ı Millî ile Lozan Antlaşması karşılaştırıldığında Misak-ı Millî\'den verilen tavizler arasında aşağıdakilerden hangisi yer alır?', 'Musul\'un Türkiye sınırları dışında kalması', ['Kapitülasyonların kaldırılması', 'Doğu Trakya\'nın Meriç\'e kadar Türkiye\'ye bırakılması', 'Osmanlı borçlarının paylaştırılması'], 'Misak-ı Millî sınırları içinde görülen Musul, Lozan\'da çözülemeyip sonradan Irak\'a bırakılmıştır; Batum, Batı Trakya ve Hatay\'ın durumu da tavizler arasında anılır.'),
  ('TBMM\'nin açılışından sonra İstanbul hükümetinin Ankara\'ya karşı izlediği politikaya örnek olarak aşağıdakilerden hangisi gösterilemez?', 'Tekâlif-i Milliye emirlerini yayımlaması', ['Kuvâ-yı İnzibatiye\'yi kurması', 'Şeyhülislamlık fetvası yayımlatması', 'Mustafa Kemal hakkında idam kararı verdirmesi'], 'Tekâlif-i Milliye emirleri Başkomutan Mustafa Kemal tarafından TBMM adına yayımlanmıştır. Diğerleri İstanbul hükümetinin Millî Mücadele\'ye karşı adımlarıdır.'),
  ('TBMM\'nin 1920-1922 yıllarında olağanüstü yetkilerle çalışmasını gerektiren temel koşul aşağıdakilerden hangisidir?', 'Savaş hâlinin sürmesi ve hızlı karar alma ihtiyacı', ['Ülkede hiç seçim yapılamaması', 'Padişahın meclise başkanlık etmesi', 'Anayasanın tümüyle kaldırılmış olması ve yasa boşluğu'], 'Cephelerde savaş sürerken kararların hızla alınması gerektiğinden TBMM yasama, yürütme ve yargıyı kendinde toplamıştır.'),
  ('Bir tarih kitabında "Bu belge, padişah ve İstanbul hükümetinin dışında yeni bir millî iradenin oluştuğunu ilk kez açıkça ortaya koyan bir ihtilal beyannamesidir" deniyor. Söz edilen belge hangisidir?', 'Amasya Genelgesi', ['Havza Genelgesi', 'Misak-ı Millî', 'Sivas Kongresi Beyannamesi'], 'Amasya Genelgesi, kurtuluşun milletin azim ve kararıyla olacağını ve yeni bir kurul oluşturulacağını açıklayarak Millî Mücadele\'nin ihtilal beyannamesi sayılmıştır.'),
  ('Bir öğrenci şöyle yazıyor: "Bu antlaşma ile hem Güney Cephesi\'nde savaşan güçlerden biri cepheden çekildi hem de TBMM ilk kez bir İtilaf devleti tarafından resmen tanındı." Öğrencinin söz ettiği antlaşma hangisidir?', '1921 Ankara Antlaşması', ['Moskova Dostluk Antlaşması', 'Kars Antlaşması', 'Gümrü Antlaşması'], 'Fransa ile imzalanan 1921 Ankara Antlaşması ile Fransa Güney Cephesi\'nden çekilmiş ve TBMM\'yi resmen tanıyan ilk İtilaf devleti olmuştur. Moskova, Kars ve Gümrü İtilaf devletleriyle yapılmamıştır.'),
  ('Bir ülkede kadınların aile hukukunda eşit haklar kazanması, ardından yerel ve genel seçimlerde oy kullanabilmesi hangi süreci yansıtır?', 'Kadın haklarının hukuki ve siyasi alanlarda aşamalı olarak genişlemesini', ['Kadın haklarının yalnızca ekonomik alanda tanınmasını', 'Kadın haklarının tek bir yasayla bir anda ve bütün alanlarda verilmesini', 'Kadın haklarının dış baskıyla zorunlu kabul edilmesini'], 'Türkiye\'de önce Medeni Kanun (1926) ile toplumsal ve hukuki eşitlik, ardından 1930-1934 arasında siyasi haklar tanınmıştır; bu aşamalı bir gelişmedir.'),
  ('Saltanatın kaldırılması, Cumhuriyetin ilanı ve halifeliğin kaldırılması arasındaki ortak amaç aşağıdakilerden hangisidir?', 'Egemenliği tümüyle millete ait kılmak', ['Ekonomide devletçiliği sağlamak', 'Dış politikada ittifak kurmak', 'Eğitimde yabancı dil öğretimini artırmak'], 'Bu üç gelişme, egemenliğin bir hanedan ya da dinî makam yerine millette olmasını sağlayan siyasi inkılaplardır.'),
  ('Halifeliğin kaldırılması Türkiye\'nin iç ve dış politikasında aşağıdaki sonuçlardan hangisini doğurmamıştır?', 'Kapitülasyonların yeniden yürürlüğe girmesi', ['Laik devlet yapısına geçişin hızlanması', 'Yabancıların halifelik aracılığıyla iç işlere karışma olanağının ortadan kalkması', 'Osmanlı hanedanının yurt dışına çıkarılması'], 'Kapitülasyonlar Lozan\'da kesin olarak kaldırılmıştır ve halifeliğin kaldırılmasıyla ilgisi yoktur. Diğer sonuçlar 3 Mart 1924 kararlarıyla ilgilidir.'),
  ('1961 ve 1982 anayasalarının ortak özelliği aşağıdakilerden hangisidir?', 'Askerî müdahalelerin ardından hazırlanıp halkoylamasıyla kabul edilmeleri', ['Millî Mücadele sırasında hazırlanmaları', 'İki meclisli yapıyı benimsemeleri', 'Saltanatı ve halifeliği kaldıran düzenlemeler içermeleri ve onaylatmaları'], '1961 Anayasası 27 Mayıs, 1982 Anayasası ise 12 Eylül müdahalesinden sonra hazırlanmış ve halkoyuyla kabul edilmiştir. İki meclisli yapı yalnız 1961\'e aittir.'),
  ('Takrir-i Sükûn Kanunu ile Hıyanet-i Vataniye Kanunu\'nun ortak amacı aşağıdakilerden hangisidir?', 'Devlete ve rejime yönelik tehditlere karşı iç güvenliği sağlamak', ['Ekonomik kalkınmayı hızlandırmak ve yatırımları artırmak amacıyla vergi koymak', 'Yabancı yatırımları teşvik etmek', 'Kadınlara siyasi haklar tanımak'], '1920\'deki Hıyanet-i Vataniye ve 1925\'teki Takrir-i Sükûn kanunları, isyan ve kargaşaya karşı devlet otoritesini korumayı amaçlamıştır.'),
  ('Kabotaj Kanunu, İzmir İktisat Kongresi ve aşarın kaldırılması birlikte değerlendirildiğinde Cumhuriyet\'in ilk yıllarındaki ekonomi politikası için hangi yargıya ulaşılabilir?', 'Ekonomik bağımsızlık ve millî ekonomi hedeflenmiştir', ['Ekonomi tümüyle yabancı sermayeye ve imtiyazlı şirketlere bırakılmıştır', 'Tarım tamamen göz ardı edilmiştir', 'Dış ticaret bütünüyle yasaklanmıştır'], 'Kabotaj yabancı ayrıcalığını kaldırmış, kongre millî ekonomi ilkelerini koymuş, aşarın kaldırılması ise köylüyü desteklemiştir; ortak hedef ekonomik bağımsızlıktır.'),
  ('1923-1929 dönemi ile 1930-1939 dönemi Türk ekonomisi karşılaştırıldığında temel fark nedir?', 'İlk dönemde özel girişim, ikinci dönemde devletçilik ağırlıktadır', ['İlk dönemde devletçilik, ikinci dönemde liberalizm ve serbest piyasa uygulanmıştır', 'İki dönemde de yalnız tarım desteklenmiştir', 'İkinci dönemde sanayileşmeden tümüyle vazgeçilmiştir'], '1923-1929 arasında özel girişim teşvik edilmiş; 1929 bunalımı ve sermaye birikiminin yetersizliği nedeniyle 1930\'lardan itibaren devletçilik benimsenmiştir.'),
  ('Bir ülke, sanayileşmek için özel sektörü teşvik eden yasalar çıkardığı hâlde istenen sonucu alamamış, ardından planlı bir kalkınma modeline geçmiştir. Bu durum Türkiye\'de hangi iki uygulamanın sırasını örnekler?', 'Teşvik-i Sanayi Kanunu ve Birinci Beş Yıllık Sanayi Planı', ['Kabotaj Kanunu ve Montrö Sözleşmesi', 'Medeni Kanun ve Soyadı Kanunu', 'Harf İnkılabı ve Millet Mektepleri\'nin açılması uygulaması'], '1927 Teşvik-i Sanayi Kanunu özel girişimi desteklemiş, beklenen sanayileşme sağlanamayınca 1934\'te Birinci Beş Yıllık Sanayi Planı uygulanmaya başlanmıştır.'),
  ('Balkan Antantı ile Sadabad Paktı karşılaştırıldığında ikisinin ortak amacı aşağıdakilerden hangisidir?', 'Bölgesel barışı ve sınır güvenliğini korumak', ['Sovyetler Birliği\'ne karşı ortak bir savaş açmak', 'Ortak para birimi oluşturmak', 'Üye ülkeleri tek devlette birleştirmek'], 'Batıda Balkan Antantı, doğuda Sadabad Paktı ile Türkiye çevresinde barış ve güvenlik kuşağı oluşturmayı amaçlamıştır.'),
  ('Türkiye\'nin Boğazlar meselesini 1936\'da savaş yerine uluslararası konferans yoluyla çözmesi hangi dış politika ilkesine uygundur?', 'Uluslararası hukuka bağlılık ve barışçılık', ['Yayılmacılık ve oldubitti politikası izlemek', 'Tek bir bloka bağımlılık', 'Dış dünyadan tümüyle kopma'], 'Türkiye, Lozan\'daki düzenlemeyi tek taraflı bozmak yerine imzacı devletleri Montrö\'de toplantıya çağırarak hukuki yolla değiştirmiştir.'),
  ('II. Dünya Savaşı\'nda Türkiye\'nin savaş dışı kalmasının olumlu ve olumsuz sonuçları birlikte düşünüldüğünde aşağıdakilerden hangisi olumsuz sonuçlardan biridir?', 'Ekonomide kıtlık ve karaborsanın ortaya çıkması', ['Ülke topraklarının savaş tahribatından korunması', 'Nüfus kaybının yaşanmaması', 'Toprak bütünlüğünün korunması'], 'Savaş dışı kalmak Türkiye\'yi yıkım ve kayıptan korumuştur; ancak seferberlik ve dış ticaretin daralması nedeniyle ekonomik sıkıntılar yaşanmıştır.'),
  ('Kıbrıs sorununun 1950\'lerden 1983\'e kadarki gelişimi aşağıdakilerin hangisinde doğru sırayla verilmiştir?', 'Kıbrıs Cumhuriyeti, Barış Harekâtı, Federe Devlet, KKTC', ['Barış Harekâtı, Kıbrıs Cumhuriyeti, KKTC, Federe Devlet', 'KKTC, Federe Devlet, Barış Harekâtı, Kıbrıs Cumhuriyeti', 'Federe Devlet, Kıbrıs Cumhuriyeti, KKTC, Barış Harekâtı'], 'Kıbrıs Cumhuriyeti 1960, Barış Harekâtı 1974, Kıbrıs Türk Federe Devleti 1975, KKTC ise 1983\'te kurulmuştur.'),
  ('24 Ocak 1980 kararlarının ardından Türkiye\'de görülen değişiklikler arasında aşağıdakilerden hangisi yer almaz?', 'Devletçi planlamaya dönüş ve ithalat yasakları', ['İhracatın vergi iadeleriyle teşvik edilmesi', 'Fiyatların serbest bırakılması', 'Türk lirasının devalüe edilmesi'], '24 Ocak kararları ihracatı teşvik eden, fiyatları serbestleştiren ve kur ayarlamasıyla dışa açılmayı amaçlayan liberal bir programdır.'),
  ('Rus Devrimi\'nin Millî Mücadele\'ye etkisi aşağıdakilerden hangisiyle en iyi açıklanır?', 'Doğu sınırında rahatlama ve Sovyet yardımı sağlanması', ['Batı Cephesi\'nde Yunanlıların güçlenmesi', 'İngiltere\'nin Anadolu\'ya daha çok asker göndermesi ve İstanbul\'u güçlendirmesi', 'TBMM\'nin komünizmi resmî ideoloji kabul etmesi'], 'Rusya savaştan çekilince Doğu Anadolu\'daki baskı azalmış; Sovyetler, Batı\'ya karşı mücadele eden TBMM\'ye silah ve para yardımı yapmıştır.'),
  ('I. ve II. Dünya savaşlarından sonra kurulan uluslararası örgütler karşılaştırıldığında BM\'yi Milletler Cemiyeti\'nden ayıran önemli bir özellik nedir?', 'ABD ve SSCB gibi büyük güçlerin baştan üye olması', ['Hiçbir büyük devletin üye olmaması', 'Yalnızca Avrupa ülkelerinin üye olabilmesi', 'Kararlarının hiçbir zaman bağlayıcı olmaması ve tavsiye niteliği taşıması'], 'Milletler Cemiyeti\'ne ABD hiç katılmamış, SSCB ise geç girmiş ve çıkarılmıştı. BM ise kuruluşundan itibaren büyük güçleri Güvenlik Konseyi\'nde daimi üye olarak barındırmıştır.'),
  ('Kore Savaşı, Küba Füze Krizi ve Vietnam Savaşı\'nın ortak özelliği aşağıdakilerden hangisidir?', 'Soğuk Savaş\'ın iki bloku arasındaki rekabetin parçası olmaları', ['Üçünün de Avrupa kıtasında yaşanması', 'Üçünde de Sovyetler Birliği\'nin doğrudan ve büyük sayıda asker göndermesi', 'Üçünün de BM Güvenlik Konseyi kararıyla başlaması'], 'Üç olay da ABD ile SSCB\'nin dolaylı ya da doğrudan karşı karşıya geldiği Soğuk Savaş bunalımlarıdır; hiçbiri Avrupa\'da yaşanmamıştır.'),
  ('Faşizm, Nazizm ve Stalin dönemi Sovyet rejiminin ortak özelliği aşağıdakilerden hangisidir?', 'Tek parti ve tek lider etrafında totaliter bir yönetim kurulması', ['Çok partili ve özgür seçimlere dayanması', 'Basın özgürlüğünü güvence altına alması', 'Ekonomiyi tümüyle serbest piyasaya ve özel şirketlerin denetimine bırakması'], 'Bu rejimler farklı ideolojilere dayansa da devletin toplumun her alanını denetlediği, muhalefetin yasaklandığı tek parti ve lider kültüne dayanan totaliter sistemlerdir.'),
  ('Versay Antlaşması ile Sevr Antlaşması\'nın ortak özelliği aşağıdakilerden hangisidir?', 'Yenilen devletlere ağır koşullar yüklemesi', ['İkisinin de hiç imzalanmamış olması', 'İkisinin de Türk tarafınca onaylanmış ve uygulanmış olması', 'İkisinin de ABD tarafından hazırlanması'], 'Her iki antlaşma da Paris Barış Konferansı sürecinde galiplerin yenilenlere dayattığı ağır koşullar içerir; Versay uygulanmış, Sevr ise uygulanamamıştır.'),
  ('Avrupa Kömür ve Çelik Topluluğu\'ndan Avrupa Birliği\'ne uzanan süreç aşağıdakilerden hangisini göstermektedir?', 'Ekonomik iş birliğinin zamanla siyasi bütünleşmeye dönüşmesini', ['Avrupa\'da ulus devletlerin tümüyle ortadan kalkmasını ve tek devlet olunmasını', 'Bütünleşmenin yalnız askerî alanda kalmasını', 'Avrupa ülkelerinin ABD\'ye katılmasını'], 'Kömür ve çelikle başlayan iş birliği ortak pazar, ortak para ve AB vatandaşlığı gibi siyasi boyutlara genişlemiştir.'),
  ('Bir tarihçi, Millî Mücadele\'nin başarısında "liderin, milletin ve ordunun birlikte hareket etmesini" belirleyici sayıyor. Bu görüşü en iyi destekleyen örnek aşağıdakilerden hangisidir?', 'Tekâlif-i Milliye ile halkın kaynaklarını orduya aktarması', ['Sevr Antlaşması\'nın İstanbul\'da imzalanması', 'İtilaf Devletleri\'nin İstanbul\'u işgal etmesi', 'Damat Ferit\'in sadrazam olması ve fetva yayımlatması'], 'Başkomutan Mustafa Kemal\'in emirleriyle halkın elindeki kaynakları orduya vermesi, lider-millet-ordu dayanışmasının en açık örneğidir.'),
  ('Mustafa Kemal\'in Samsun\'a çıkışından TBMM\'nin açılışına kadar geçen sürede yaptığı faaliyetlerin ortak amacı aşağıdakilerden hangisidir?', 'Millî iradeyi temsil eden bir yönetim oluşturmak', ['Osmanlı Devleti\'nin sınırlarını genişletmek', 'İtilaf Devletleri ile ittifak kurmak', 'Ekonomik bağımsızlığı sağlayacak bankalar kurmak'], 'Genelgeler, kongreler, Temsil Heyeti ve en sonunda TBMM\'nin açılışı, millî egemenliğe dayanan yeni bir yönetim kurma sürecinin aşamalarıdır.'),
  ('TBMM\'nin açılışından önce yapılan dualar, Kur\'an okunması ve kurban kesilmesi gibi törenler hangi amaca yöneliktir?', 'Halkın meclise desteğini kazanmak ve propagandaya karşı koymak', ['Meclisin dinî bir kurum olduğunu ilan etmek', 'Halifenin meclisi açtığını göstermek', 'Saltanatın sürdüğünü duyurmak ve padişaha bağlılık bildirmek'], 'İstanbul\'un fetvalarla Ankara\'yı din dışı göstermeye çalıştığı ortamda, açılış törenleri halkın meclise güvenini sağlamaya yöneliktir.'),
  ('Sevr Antlaşması ile Lozan Antlaşması kapitülasyonlar bakımından karşılaştırıldığında aşağıdakilerden hangisi doğrudur?', 'Sevr kapitülasyonları genişletmiş, Lozan tümüyle kaldırmıştır', ['Sevr kapitülasyonları kaldırmış, Lozan geri getirmiştir', 'İki antlaşma da kapitülasyonları korumuştur', 'İki antlaşmada da kapitülasyonlara hiç değinilmemiştir'], 'Sevr kapitülasyonları bütün İtilaf devletlerine genişletmişti; Lozan ise kapitülasyonları kesin olarak kaldırmıştır.'),
  ('Tevhid-i Tedrisat Kanunu ile Harf İnkılabı arasındaki ilişki için aşağıdakilerden hangisi söylenebilir?', 'Birincisi eğitimde birliği, ikincisi okuryazarlığın yaygınlaşmasını hedefler', ['İkisi de ekonomik bağımsızlığı amaçlar', 'Birincisi Lozan\'dan, ikincisi Sevr\'den kaynaklanır', 'İkisi de dış politika düzenlemesidir'], 'Tevhid-i Tedrisat eğitimdeki ikiliği kaldırıp bütün okulları tek çatı altında toplamış, Harf İnkılabı ise okuma yazmayı kolaylaştırarak eğitim seferberliğine destek olmuştur.'),
  ('Soyadı Kanunu ile lakap ve unvanların kaldırılması birlikte düşünüldüğünde hangi ilkenin uygulandığı söylenebilir?', 'Halkçılık', ['Devletçilik', 'Cumhuriyetçilik', 'Laiklik'], 'Kişiler arasında ayrıcalık ve sınıf farkı yaratan unvanların kaldırılması ve herkese soyadı verilmesi, kanun önünde eşitliği esas alan halkçılık ilkesinin uygulamasıdır.'),
  ('Bir ekonomi tarihçisi, "Bu kurum devlet eliyle kurulmuş, dokuma ve kâğıt gibi alanlarda fabrikalar açmış ve devletçiliğin simgesi olmuştur" diyor. Söz edilen kurum hangisidir?', 'Sümerbank', ['Türkiye İş Bankası', 'Ziraat Bankası', 'Osmanlı Bankası'], '1933\'te kurulan Sümerbank, Birinci Beş Yıllık Sanayi Planı\'ndaki dokuma ve diğer sanayi yatırımlarını üstlenmiştir. İş Bankası ise özel sermayeli bir bankadır.'),
  ('Atatürk döneminde Türkiye\'nin Sovyetler Birliği ile iyi ilişkiler kurarken aynı zamanda Batılı devletlerle de yakınlaşması hangi dış politika anlayışını gösterir?', 'Dengeli ve çok yönlü bir politika', ['Tamamen Sovyet blokuna bağlı bir politika', 'Bütün komşularla çatışmacı bir politika', 'Batı\'ya karşı yalnızlıkçı bir politika'], 'Türkiye bir yandan Sovyetlerle 1925 dostluk antlaşmasını imzalamış ve sanayi kredisi almış, diğer yandan Milletler Cemiyeti ve Balkan Antantı ile Batı\'ya yaklaşmıştır.'),
  ('Köy Enstitüleri\'nin eğitim anlayışı aşağıdakilerden hangisiyle en iyi tanımlanır?', 'İş içinde ve üretime dayalı uygulamalı eğitim', ['Yalnızca kuramsal dersler veren seçkinci eğitim', 'Dinî eğitime ağırlık veren medrese tipi eğitim', 'Yalnız yabancı dil öğreten kolej tipi eğitim'], 'Köy Enstitüleri öğrencilere tarım, yapı ve zanaat gibi işleri yaparak öğretmiş; yetişen öğretmenler köylerde hem eğitimci hem de kalkınma öncüsü olmuştur.'),
  ('DP döneminde karayollarının yaygınlaşması ve tarımda makineleşme ile 1923-1938 arasındaki demiryolu politikası karşılaştırıldığında hangi değişim görülür?', 'Ulaşımda ağırlığın demiryolundan karayoluna kayması', ['Ulaşım yatırımlarının tümüyle durdurulması', 'Demiryollarının yabancı şirketlere geri verilmesi', 'Deniz ulaşımının tamamen yasaklanması'], 'Atatürk döneminde demiryolu yapımı öne çıkarken 1950\'lerde Marshall yardımlarıyla karayolu yapımı hızlanmış ve ulaşımda karayolu ağırlık kazanmıştır.'),
  ('1950\'lerin sonunda DP iktidarının muhalefete yönelik baskıcı uygulamalarının artması hangi sonucu doğurmuştur?', 'Siyasi gerginliğin tırmanarak askerî müdahaleye zemin hazırlaması', ['CHP\'nin kapatılıp DP\'ye katılması', 'Türkiye\'nin NATO\'dan ayrılması', 'Seçimlerin tümüyle kaldırılması ve krallığa geçilmesi'], 'Basın kısıtlamaları ve Tahkikat Komisyonu gibi uygulamalar öğrenci olaylarına ve kutuplaşmaya yol açmış; süreç 27 Mayıs 1960 müdahalesiyle sonuçlanmıştır.'),
  ('1980\'ler Türkiye\'sinde ekonomik liberalleşme ile 1930\'lar Türkiye\'sindeki devletçilik karşılaştırıldığında temel fark nedir?', 'Devletin ekonomideki ağırlığının azaltılması', ['Devletin bütün sanayiyi kurup işletmesi', 'Dış ticaretin tümüyle yasaklanması', 'Planlı ekonomiye ilk kez geçilmesi'], '1930\'larda devlet sanayinin öncüsüyken, 1980\'lerde 24 Ocak kararları ve özelleştirme ile piyasa ekonomisi ve özel sektör öne çıkarılmıştır.'),
  ('I. Dünya Savaşı ile II. Dünya Savaşı karşılaştırıldığında yalnızca II. Dünya Savaşı için söylenebilecek özellik hangisidir?', 'Atom bombasının kullanılması', ['Siper savaşlarının yapılması', 'Denizaltıların kullanılması', 'Osmanlı Devleti\'nin savaşa katılması'], 'Atom bombası ilk ve tek kez II. Dünya Savaşı\'nda kullanılmıştır. Siper savaşları I. Dünya Savaşı\'nın, denizaltılar ise iki savaşın ortak özelliğidir; Osmanlı yalnız birincisine katılmıştır.'),
  ('1919\'da kurulan Weimar Cumhuriyeti\'nin çöküşünde aşağıdakilerden hangisinin etkisi yoktur?', 'Marshall Planı yardımlarının kesilmesi', ['Versay\'ın ağır tazminat yükü', '1923 hiperenflasyonu', '1929 Büyük Buhranı ve işsizlik'], 'Marshall Planı 1947\'de, yani Weimar Cumhuriyeti\'nin sona ermesinden çok sonra başlamıştır. Diğerleri Weimar\'ı zayıflatan etkenlerdir.'),
  ('Bir tarihçi "Bu konferans, saldırgan bir devlete taviz vererek barışı korumaya çalışmanın başarısız olduğunu gösteren en çarpıcı örnektir" diyor. Tarihçinin söz ettiği konferans hangisidir?', 'Münih Konferansı', ['Yalta Konferansı', 'Bandung Konferansı', 'Bretton Woods Konferansı'], '1938 Münih\'te Südet bölgesinin Almanya\'ya verilmesi savaşı önleyememiş; Almanya 1939\'da Çekoslovakya\'nın kalanını işgal etmiş ve ardından Polonya\'ya saldırmıştır.'),
  ('Truman Doktrini, NATO\'nun kurulması ve Kore Savaşı\'na müdahale birlikte değerlendirildiğinde ABD\'nin hangi stratejisi açıkça görülür?', 'Komünizmi çevreleme', ['Yalnızcılık ve içe kapanma', 'Sömürgeleri genişletme', 'Sovyetlerle ittifak kurma'], 'Üç gelişme de Sovyet etkisinin yeni bölgelere yayılmasını önlemeye yönelik çevreleme stratejisinin ürünleridir.'),
  ('Doğu bloku ülkelerinde 1953 Doğu Berlin, 1956 Macaristan ve 1968 Çekoslovakya olaylarının ortak sonucu nedir?', 'Sovyet askerî gücüyle bastırılmaları', ['Ülkelerin NATO\'ya katılması', 'Komünist rejimlerin hemen yıkılması', 'Ülkelerin bağımsız tarafsız devlet olması'], 'Üç ayaklanma ya da reform girişimi de Sovyet ya da Varşova Paktı birlikleri tarafından bastırılmıştır; komünist rejimler ancak 1989\'da çökmüştür.'),
  ('Sputnik\'in fırlatılmasından sonra ABD\'de matematik ve fen eğitimine büyük yatırım yapılması aşağıdakilerden hangisini gösterir?', 'Uzay yarışının eğitim politikalarını da etkilediğini', ['ABD\'nin uzay araştırmalarını tümüyle durdurduğunu', 'Sovyetlerin ABD\'ye eğitim yardımı yaptığını', 'Eğitimin askerî alanla hiç ilgisi olmadığını'], 'Sputnik şoku ABD\'de teknolojik geride kalma kaygısı yaratmış ve 1958\'de çıkarılan eğitim yasasıyla fen ve matematik eğitimine büyük kaynak ayrılmıştır.'),
  ('Hindistan ve Cezayir\'in bağımsızlık süreçleri karşılaştırıldığında aradaki temel fark nedir?', 'Hindistan ağırlıklı olarak barışçı direnişle, Cezayir uzun bir silahlı savaşla bağımsız olmuştur', ['Hindistan Fransa\'dan, Cezayir İngiltere\'den bağımsız olmuştur', 'İkisi de aynı yıl bağımsız olmuştur', 'Hindistan silahlı savaşla, Cezayir halk oylamasıyla bağımsız olmuştur'], 'Hindistan Gandi\'nin şiddetsiz direnişiyle 1947\'de İngiltere\'den, Cezayir ise 1954-1962 savaşı sonunda Fransa\'dan bağımsız olmuştur.'),
  ('Arap-İsrail savaşları sırasıyla verildiğinde doğru kronoloji hangisidir?', '1948 Savaşı, Süveyş Krizi, Altı Gün Savaşı, Yom Kippur Savaşı', ['Süveyş Krizi, 1948 Savaşı, Yom Kippur Savaşı, Altı Gün Savaşı', 'Altı Gün Savaşı, 1948 Savaşı, Süveyş Krizi, Yom Kippur Savaşı', '1948 Savaşı, Altı Gün Savaşı, Süveyş Krizi, Yom Kippur Savaşı'], 'Sıralama 1948, 1956 (Süveyş), 1967 (Altı Gün) ve 1973 (Yom Kippur) şeklindedir.'),
  ('Mao dönemi Çin\'i ile Deng Xiaoping dönemi Çin\'i karşılaştırıldığında aşağıdakilerden hangisi Deng dönemine özgüdür?', 'Yabancı yatırıma açılan özel ekonomik bölgeler', ['Kızıl Muhafızlar\'ın kurulması', 'Köy komünlerinin oluşturulması', 'Büyük İleri Atılım\'ın başlatılması'], 'Deng döneminde Shenzhen gibi özel ekonomik bölgeler kurulmuş ve yabancı sermayeye kapı açılmıştır; diğerleri Mao dönemi uygulamalarıdır.'),
  ('SSCB\'nin dağılması ile Yugoslavya\'nın dağılması karşılaştırıldığında Yugoslavya\'yı ayıran özellik nedir?', 'Dağılmanın uzun ve kanlı iç savaşlarla gerçekleşmesi', ['Dağılmanın tümüyle barışçı olması', 'Yeni devletlerin BM üyeliğine kabul edilmemesi', 'Dağılmanın II. Dünya Savaşı\'ndan önce olması'], 'SSCB\'nin dağılması görece barışçı olmuşken Yugoslavya\'nın dağılması Hırvatistan, Bosna ve Kosova\'daki savaşlarla büyük can kayıplarına yol açmıştır.'),
  ('Atatürk\'ün 1927\'de Nutuk\'u okuması ile 1933\'te Onuncu Yıl Nutku\'nu okuması arasındaki fark hangisinde doğru verilmiştir?', 'Nutuk geçmişin hesabını verir, Onuncu Yıl Nutku geleceğe hedef koyar', ['Nutuk geleceğe hedef koyar, Onuncu Yıl Nutku geçmişi anlatır', 'İkisi de yalnızca dış politika konularını işler', 'İkisi de Millî Mücadele\'den önce okunmuştur'], 'Nutuk 1919-1927 olaylarını belgeleriyle anlatırken, Onuncu Yıl Nutku muasır medeniyetin üstüne çıkma gibi gelecek hedeflerini ortaya koymuştur.'),
  ('Bir yazar şöyle diyor: "Bu kanun Mustafa Kemal\'e geniş yetkiler vermiş ama meclisin üstünlüğünü ortadan kaldırmamıştı; çünkü yetkiler süreliydi ve meclis istediği zaman geri alabilirdi." Yazar hangi kanunu anlatmaktadır?', 'Başkomutanlık Kanunu', ['Hıyanet-i Vataniye Kanunu', 'Takrir-i Sükûn Kanunu', 'Teşkilât-ı Esasiye Kanunu'], '1921\'de üç ay için çıkarılan ve birkaç kez uzatılan Başkomutanlık Kanunu, meclisin yetkilerini Mustafa Kemal\'e geçici ve geri alınabilir biçimde devretmiştir.'),
  ('Aşağıdakilerden hangisi Mudanya Ateşkes Antlaşması\'nın Lozan Konferansı\'na zemin hazırladığını gösterir?', 'İtilaf Devletleri\'nin TBMM\'yi muhatap alarak savaşı resmen durdurması', ['Yunanistan\'ın İzmir\'i yeniden işgal etmesi', 'Sevr Antlaşması\'nın onaylanması', 'Osmanlı hükümetinin yetkilerinin artırılması'], 'Mudanya ile Türk-Yunan savaşı resmen sona ermiş ve İtilaf Devletleri barış görüşmeleri için TBMM\'yi muhatap kabul etmiştir.'),
  ('Türk Tarih Kurumu ile Türk Dil Kurumu\'nun kuruluşunda Atatürk\'ün izlediği yöntemde ortak olan özellik aşağıdakilerden hangisidir?', 'Kültürel inkılapları bilimsel kurumlar aracılığıyla yürütmek', ['Kültürel çalışmaları yabancı devletlere bırakmak', 'Tarih ve dil araştırmalarını yasaklamak', 'Bu kurumları yalnız askerî amaçla kullanmak'], 'Atatürk, tarih ve dil alanındaki çalışmaları kalıcı ve bilimsel temele oturtmak için bağımsız araştırma kurumları kurdurmuş ve kurultaylar düzenletmiştir.'),
  ('Türkiye\'de kadınlara milletvekili seçme ve seçilme hakkının pek çok Avrupa ülkesinden önce tanınması nasıl değerlendirilebilir?', 'Cumhuriyet\'in çağdaşlaşma hedefinde öncü bir adım attığı', ['Avrupa\'nın Türkiye\'yi bu konuda zorladığı', 'Kadın haklarının yalnız kâğıt üzerinde kaldığı ve hiç uygulanmadığı', 'Bu hakkın Osmanlı döneminde zaten var olduğu'], 'Türkiye 1934\'te bu hakkı tanırken Fransa (1944) ve İtalya (1946) gibi ülkelerde kadınlar henüz genel seçimlerde oy kullanamıyordu.'),
];
